create or replace function public.company_pitches_state(p_company uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'event_id', (select e.id from public.player_company_events e
                  where e.company_id = p_company and e.status in ('open', 'in_force')
                  order by e.started_at desc limit 1),
    'event_cost_cents', public.company_event_unit_cents(p_company) * (public.pitches_cfg() ->> 'eventCostUnits')::integer,
    'move_cost_cents', (select round((public.config_jsonb('companyMoves') -> 'costCentsByTier' ->> pc.tier::text)::numeric
                                     * (public.pitches_cfg() ->> 'moveCostFactor')::numeric)::bigint
                          from public.player_companies pc where pc.company_id = p_company),
    -- when the next free order may start (ADR-139): null = now
    'next_order_at', (select case when max(x.created_at) + make_interval(mins => coalesce((public.pitches_cfg() ->> 'orderCooldownMinutes')::integer, 60))
                                       > public.game_now()
                                  then max(x.created_at) + make_interval(mins => coalesce((public.pitches_cfg() ->> 'orderCooldownMinutes')::integer, 60)) end
                        from public.company_pitches x where x.company_id = p_company and x.kind = 'move'),
    'pitches', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', p.id, 'kind', p.kind, 'move_kind', p.move_kind, 'event_id', p.event_id, 'text', p.pitch_text,
               'status', p.status, 'judge', p.judge, 'fit', p.fit, 'backfire', p.backfire, 'chance_bps', p.chance_bps,
               'verdict', p.verdict, 'success_text', p.success_text, 'failure_text', p.failure_text,
               'backfire_text', p.backfire_text, 'cost_cents', p.cost_cents, 'result_cents', p.result_cents,
               'created_at', p.created_at, 'ends_at', p.ends_at, 'resolved_at', p.resolved_at)
             order by p.created_at desc)
        from (select * from public.company_pitches x where x.company_id = p_company
               order by x.created_at desc limit 8) p), '[]'::jsonb));
$$;

create or replace function public.submit_company_pitch(p_request_id uuid, p_kind text, p_text text,
                                                       p_move_kind text default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  cfg      jsonb := public.pitches_cfg();
  v_player uuid;
  v_replay jsonb;
  pc       public.player_companies;
  v_text   text := btrim(coalesce(p_text, ''));
  v_event  uuid;
  v_cost   bigint;
  v_cash   bigint;
  v_state  jsonb;
begin
  v_player := public.require_player();
  if p_request_id is null or p_kind not in ('event', 'move')
     or (p_kind = 'move' and coalesce(p_move_kind, '') not in ('cash', 'awareness', 'quality')) then
    perform public.api_error('invalid_argument');
  end if;
  if length(v_text) < (cfg ->> 'minChars')::integer or length(v_text) > (cfg ->> 'maxChars')::integer
     or v_text ~ '[\x00-\x08\x0b-\x1f]' or public.text_has_profanity(v_text) then
    perform public.api_error('pitch_text_invalid');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'submit_company_pitch');
  if v_replay is not null then
    return v_replay;
  end if;
  select * into pc from public.player_companies where founder_id = v_player and status = 'active' for update;
  if pc.company_id is null then
    perform public.api_error('company_not_found');
  end if;
  v_state := public.company_pitches_state(pc.company_id);
  if p_kind = 'event' then
    v_event := (v_state ->> 'event_id')::uuid;
    if v_event is null then
      perform public.api_error('event_closed');
    end if;
    if exists (select 1 from public.company_pitches p where p.event_id = v_event and p.status in ('judging', 'running')) then
      perform public.api_error('pitch_busy');
    end if;
    v_cost := (v_state ->> 'event_cost_cents')::bigint;
  else
    -- own moves share the slots of the business moves (ADR-127)
    if (select count(*) from public.company_moves m where m.company_id = pc.company_id and m.status = 'running')
       + (select count(*) from public.company_pitches p where p.company_id = pc.company_id and p.kind = 'move'
            and p.status in ('judging', 'running'))
       >= (public.config_jsonb('companyMoves') -> 'slotsByTier' ->> pc.tier::text)::integer then
      perform public.api_error('pitch_busy');
    end if;
    -- one free order per hour (ADR-139); only an order that was carried out counts
    if (v_state ->> 'next_order_at') is not null then
      perform public.api_error('order_cooldown');
    end if;
    v_cost := (v_state ->> 'move_cost_cents')::bigint;
  end if;
  select a.balance_cents into v_cash from public.ledger_accounts a
   where a.id = public.company_cash_account(pc.company_id) for update;
  if coalesce(v_cash, 0) < v_cost then
    perform public.api_error('insufficient_funds');
  end if;
  if v_cost > 0 then
    perform public.ledger_transfer(public.company_cash_account(pc.company_id), public.ledger_system_account('households'),
                                   v_cost, 'company_costs', 'Eigene Strategie', 'company', pc.company_id,
                                   'pitch:start:' || p_request_id::text, v_player, jsonb_build_object('kind', p_kind));
  end if;
  insert into public.company_pitches (company_id, event_id, kind, move_kind, pitch_text, cost_cents, created_by,
                                      created_at, judge_due_at)
  values (pc.company_id, v_event, p_kind, case when p_kind = 'move' then p_move_kind end, v_text, v_cost, v_player,
          public.game_now(), public.game_now() + make_interval(secs => (cfg ->> 'judgeWaitSeconds')::integer));
  return public.request_complete(v_player, p_request_id, public.company_pitches_state(pc.company_id));
end;
$$;

create or replace function public.company_assistant_context(p_text text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  cfg       jsonb := public.company_assistant_cfg();
  v_player  uuid := public.require_player();
  v_tasks   jsonb;
  v_company uuid;
  v_founder boolean;
  v_moves   jsonb;
  pc        public.player_companies;
  c         public.companies;
  e         public.player_company_events;
begin
  if p_text is null or char_length(btrim(p_text)) not between 1 and coalesce((cfg ->> 'maxTextLength')::int, 300) then
    perform public.api_error('invalid_argument');
  end if;
  v_tasks := public.company_tasks_state(v_player);  -- company_not_found without a company
  v_company := (v_tasks -> 'company' ->> 'id')::uuid;
  v_founder := v_tasks ->> 'role' = 'founder';

  -- the hourly limit (serialised per player, so parallel calls cannot slip through)
  perform pg_advisory_xact_lock(hashtextextended('company_assistant:' || v_player::text, 0));
  if (select count(*) from public.company_assistant_calls a
       where a.player_id = v_player and a.created_at > now() - interval '1 hour')
     >= coalesce((cfg ->> 'claudePerHour')::int, 20) then
    perform public.api_error('assistant_busy');
  end if;
  insert into public.company_assistant_calls (player_id) values (v_player);
  delete from public.company_assistant_calls a where a.player_id = v_player and a.created_at < now() - interval '1 day';

  select * into pc from public.player_companies where company_id = v_company;
  select * into c from public.companies where id = v_company;
  if v_founder then
    v_moves := public.company_moves_state(v_company);
    select * into e from public.player_company_events ev
     where ev.company_id = v_company and ev.status = 'open'
     order by ev.started_at desc limit 1;
  end if;

  return jsonb_build_object(
    'text', btrim(p_text),
    'role', v_tasks ->> 'role',
    'company', jsonb_build_object('name', c.name, 'idea', pc.idea, 'product', pc.product_key, 'sector', c.sector_key,
                                  'tier', pc.tier),
    'tasks', v_tasks,
    'moves', v_moves,
    -- free orders (ADR-139): cost, when the next one may start, how the last ones went
    'orders', case when v_founder then public.company_pitches_state(v_company) end,
    'last_quarter', (select jsonb_build_object('revenue_cents', q.revenue_cents, 'profit_cents', q.net_income_cents)
                       from public.company_quarter_reports q where q.company_id = v_company
                      order by q.game_quarter_id desc limit 1),
    'event', case when e.id is null then null else jsonb_build_object(
               'archetype', e.archetype, 'polarity', e.polarity, 'severity', e.severity, 'headline', e.ai_headline) end);
end;
$$;

-- ===== supabase/migrations/20261204001300_task_ranges.sql =====
-- =============================================================================
-- NEXA · 1300 · Task games you solve by thinking (ADR-140)
-- =============================================================================
-- The order game drew every value from 1..99, so a shift could start at "73 Uhr". Each order task now has its own
-- realistic range (companyTasks.tasks[].range, e.g. 6..22 Uhr); without one the game's default applies.
-- Only company_task_puzzle() changes. Idempotent: runs unchanged as supabase/updates/20261204001300_task_ranges.sql.

create or replace function public.company_task_puzzle(p_task jsonb)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  g        jsonb := public.company_tasks_cfg() -> 'games' -> (p_task ->> 'game');
  v_game   text := p_task ->> 'game';
  v_n      integer;
  v_tiles  jsonb;
  v_sol    jsonb;
  v_vals   integer[] := '{}';
  v_v      integer;
  a        integer;
  b        integer;
begin
  if v_game in ('pick', 'count') then
    v_n := public.rand_between((g ->> 'minTargets')::integer, (g ->> 'maxTargets')::integer);
    with t as (
      select i, case when i <= v_n then 0 else 1 + floor(random() * 2)::integer end as lab
        from generate_series(1, (g ->> 'tiles')::integer) i),
    s as (select lab, row_number() over (order by random()) - 1 as pos from t)
    select jsonb_agg(lab order by pos), coalesce(jsonb_agg(pos order by pos) filter (where lab = 0), '[]'::jsonb)
      into v_tiles, v_sol from s;
    if v_game = 'pick' then
      return jsonb_build_object('puzzle', jsonb_build_object('tiles', v_tiles), 'solution', jsonb_build_object('targets', v_sol));
    end if;
    return jsonb_build_object('puzzle', jsonb_build_object('tiles', v_tiles), 'solution', jsonb_build_object('count', v_n));
  elsif v_game = 'sort' then
    with s as (select i, row_number() over (order by random()) as pos from generate_series(0, (g ->> 'items')::integer - 1) i)
    select jsonb_agg(i order by pos), jsonb_agg(case when i < (g ->> 'items')::integer / 2 then 0 else 1 end order by pos)
      into v_tiles, v_sol from s;
    return jsonb_build_object('puzzle', jsonb_build_object('items', v_tiles), 'solution', jsonb_build_object('sides', v_sol));
  elsif v_game = 'order' then
    while coalesce(array_length(v_vals, 1), 0) < (g ->> 'items')::integer loop
      -- the task's own realistic range (ADR-140), else the game's default
      v_v := public.rand_between(coalesce((p_task -> 'range' ->> 0)::integer, (g ->> 'min')::integer),
                                 coalesce((p_task -> 'range' ->> 1)::integer, (g ->> 'max')::integer));
      if not v_v = any (v_vals) then
        v_vals := v_vals || v_v;
      end if;
    end loop;
    select jsonb_agg(i - 1 order by case when coalesce((p_task ->> 'asc')::boolean, true) then v else -v end)
      into v_sol from unnest(v_vals) with ordinality as x(v, i);
    return jsonb_build_object('puzzle', jsonb_build_object('values', to_jsonb(v_vals)),
                              'solution', jsonb_build_object('order', v_sol));
  elsif v_game = 'seq' then
    select jsonb_agg(floor(random() * 4)::integer) into v_sol from generate_series(1, (g ->> 'length')::integer);
    return jsonb_build_object('puzzle', jsonb_build_object('sequence', v_sol, 'show_seconds', (g ->> 'showSeconds')::integer),
                              'solution', jsonb_build_object('sequence', v_sol));
  elsif v_game = 'math' then
    a := public.rand_between((p_task -> 'a' ->> 0)::integer, (p_task -> 'a' ->> 1)::integer);
    b := public.rand_between((p_task -> 'b' ->> 0)::integer, (p_task -> 'b' ->> 1)::integer);
    if p_task ->> 'op' = 'pct' then
      -- whole results: big amounts in hundreds, small ones in tens with rates in tens
      if (p_task -> 'a' ->> 1)::integer >= 1000 then
        a := greatest(100, (a / 100) * 100);
      else
        a := greatest(10, (a / 10) * 10);
        b := greatest(10, (b / 10) * 10);
      end if;
    end if;
    v_v := case p_task ->> 'op' when 'mul' then a * b when 'add' then a + b when 'sub' then a - b
                                when 'pct' then a * b / 100 end;
    return jsonb_build_object('puzzle', jsonb_build_object('a', a, 'b', b), 'solution', jsonb_build_object('value', v_v));
  end if;
  raise exception 'unknown task game %', v_game;
end;
$$;

-- ===== supabase/migrations/20261204001400_nft_market.sql =====
-- =============================================================================
-- NEXA · 1400 · A living NFT market: the AI collectors trade among themselves (ADR-141)
-- =============================================================================
-- Popular NFTs are wanted: open offers and sales of the last days raise what the collectors pay (nft_demand_bps, on
-- top of likes). The collectors trade among themselves: per minute an NFT a collector holds is bought by another one
-- with a chance that grows with popularity; the price follows the buyer's taste around the fair value (mint cost or
-- floor x bonuses, not the last price) and moves part of the way from the last price, so prices go up and down. The
-- buyer offers it again (nft_after_sale). The money stays with the households; the creator gets the royalty.
-- Port of src/lib/sim/nfts.ts (nftDemandBps, nftFairCents, nftAiTradeChanceBps, nftAiTradePriceCents).
-- Idempotent: runs unchanged as supabase/updates/20261204001400_nft_market.sql.

create or replace function public.nft_after_sale(p_artwork uuid, p_seller uuid, p_seller_ai text, p_buyer uuid, p_buyer_ai text,
                                                 p_price bigint, p_fee bigint, p_royalty bigint, p_kind text,
                                                 p_auction uuid, p_accepted bigint)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  a       public.artworks;
  v_buyer text;
  v_now   timestamptz := public.game_now();
begin
  v_buyer := coalesce(p_buyer_ai, (select p.nickname from public.profiles p where p.id = p_buyer), 'Ehemaliger Spieler');
  update public.artworks
     set owner_id = p_buyer, ai_owner = p_buyer_ai, value_cents = p_price, ask_cents = null, listed_at = null
   where id = p_artwork
  returning * into a;
  insert into public.artwork_sales (artwork_id, auction_id, seller_id, buyer_id, seller_ai, buyer_ai, price_cents, fee_cents,
                                    royalty_cents, creator_id, kind, at)
  values (a.id, p_auction, p_seller, p_buyer, p_seller_ai, p_buyer_ai, p_price, p_fee, p_royalty,
          case when p_royalty > 0 then a.creator_id end, p_kind, v_now);
  update public.artwork_messages set offer_status = 'closed'
   where artwork_id = a.id and offer_status = 'open' and id is distinct from p_accepted;
  -- an AI collector offers what it bought at its valuation (this sale included; offers that just closed no longer count as demand, ADR-141) x resaleMarkup
  if p_buyer_ai is not null then
    update public.artworks set ask_cents = public.nft_ai_ask_cents(public.nft_ai_value_cents(a.id, v_now)), listed_at = v_now
     where id = a.id;
  end if;
  insert into public.artwork_messages (artwork_id, kind, body, offer_cents, created_at)
  values (a.id, 'sale', left(v_buyer, 200), p_price, v_now);
  if p_kind <> 'auction' then
    if p_seller is not null then
      perform public.social_notify(p_seller, 'nft_sale', '„' || a.title || '“ verkauft',
        v_buyer || ' hat dein NFT ' || public.artwork_code(a.serial) || ' für ' || public.format_eur(p_price) || ' gekauft.',
        jsonb_build_object('artwork_id', a.id, 'code', public.artwork_code(a.serial), 'title', a.title,
                           'price_cents', p_price, 'buyer', v_buyer),
        '/artworks', 'nft_sale:' || a.id::text || ':' || extract(epoch from v_now)::bigint::text);
      perform public.mission_event(p_seller, 'art_sold', 1, null);
    end if;
    if p_buyer is not null then
      perform public.mission_event(p_buyer, 'nft_bought', 1, null);
    end if;
  end if;
end;
$$;

create or replace function public.nft_demand_bps(p_artwork uuid, p_now timestamptz default null,
                                              p_exclude uuid default null)
returns bigint
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce((d ->> 'offerBps')::bigint, 0)
           * least((select count(distinct coalesce(m.author_id::text, m.ai_name)) from public.artwork_messages m
                     where m.artwork_id = p_artwork and m.offer_status = 'open'
                       and (p_exclude is null or m.author_id is distinct from p_exclude)), coalesce((d ->> 'maxOffers')::bigint, 0))
       + coalesce((d ->> 'saleBps')::bigint, 0)
           * least((select count(*) from public.artwork_sales s
                     where s.artwork_id = p_artwork
                       and s.at >= coalesce(p_now, public.game_now()) - make_interval(days => coalesce((d ->> 'days')::integer, 7))),
                   coalesce((d ->> 'maxSales')::bigint, 0))
    from (select coalesce(public.nfts_cfg() #> '{ai,demand}', '{}'::jsonb) as d) c;
$$;

create or replace function public.nft_fair_cents(p_artwork uuid, p_now timestamptz default null)
returns bigint
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  ai      jsonb := public.nfts_cfg() -> 'ai';
  a       public.artworks;
  v_base  bigint;
  v_likes bigint;
  v_sales bigint := 0;
  v_days  bigint;
begin
  select * into a from public.artworks where id = p_artwork;
  if a.id is null then
    return null;
  end if;
  v_base := greatest(coalesce(a.mint_cents, case when a.origin = 'game' then public.artwork_gallery_start_cents(a.rarity) end, 0),
                     coalesce((ai ->> 'floorCents')::bigint, 100000));
  select count(*) into v_likes from public.artwork_likes l where l.artwork_id = a.id;
  if a.creator_id is not null then
    select count(*) into v_sales from public.artwork_sales s join public.artworks x on x.id = s.artwork_id
     where x.creator_id = a.creator_id;
  end if;
  v_days := greatest(0, floor(extract(epoch from (coalesce(p_now, public.game_now()) - a.created_at)) / 86400))::bigint;
  return floor(v_base::numeric * (10000
           + (ai ->> 'likeBps')::bigint * least(v_likes, (ai ->> 'maxLikes')::bigint)
           + (ai ->> 'creatorSaleBps')::bigint * least(v_sales, (ai ->> 'maxCreatorSales')::bigint)
           + (ai ->> 'ageBpsPerDay')::bigint * least(v_days, (ai ->> 'maxAgeDays')::bigint)
           + public.nft_demand_bps(a.id, p_now)) / 10000)::bigint;
end;
$$;

create or replace function public.nft_ai_trade_price_cents(p_last bigint, p_fair bigint, p_u double precision)
returns bigint
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  cfg      jsonb := public.nfts_cfg();
  t        jsonb := public.nfts_cfg() #> '{ai,trade}';
  v_taste  integer;
  v_target bigint;
  v_last   bigint;
begin
  v_taste := (t ->> 'tasteMinBps')::integer
           + floor(least(greatest(coalesce(p_u, 0), 0), 0.999999) * ((t ->> 'tasteMaxBps')::integer - (t ->> 'tasteMinBps')::integer))::integer;
  v_target := floor(p_fair::numeric * v_taste / 10000)::bigint;
  v_last := coalesce(p_last, v_target);
  return greatest((cfg ->> 'minAskCents')::bigint,
                  (round((v_last + trunc((v_target - v_last)::numeric * (t ->> 'reversionBps')::integer / 10000)) / 100.0) * 100)::bigint);
end;
$$;

-- The valuation without the demand of one bidder: their own offer must not raise the price they have to beat.
create or replace function public.nft_ai_value_excluding(p_artwork uuid, p_now timestamptz, p_exclude uuid)
returns bigint
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  ai       jsonb := public.nfts_cfg() -> 'ai';
  a        public.artworks;
  v_anchor bigint;
  v_likes  bigint;
  v_sales  bigint := 0;
  v_days   bigint;
  v_bonus  bigint;
begin
  select * into a from public.artworks where id = p_artwork;
  if a.id is null then
    return null;
  end if;
  v_anchor := greatest(coalesce(a.value_cents, 0),
                       coalesce(a.mint_cents, case when a.origin = 'game' then public.artwork_gallery_start_cents(a.rarity) end, 0),
                       coalesce((ai ->> 'floorCents')::bigint, 100000));
  select count(*) into v_likes from public.artwork_likes l where l.artwork_id = a.id;
  if a.creator_id is not null then
    select count(*) into v_sales from public.artwork_sales s join public.artworks x on x.id = s.artwork_id
     where x.creator_id = a.creator_id;
  end if;
  v_days := greatest(0, floor(extract(epoch from (coalesce(p_now, public.game_now()) - a.created_at)) / 86400))::bigint;
  v_bonus := coalesce((ai ->> 'likeBps')::bigint, 400) * least(v_likes, coalesce((ai ->> 'maxLikes')::bigint, 40))
           + coalesce((ai ->> 'creatorSaleBps')::bigint, 300) * least(v_sales, coalesce((ai ->> 'maxCreatorSales')::bigint, 10))
           + coalesce((ai ->> 'ageBpsPerDay')::bigint, 100) * least(v_days, coalesce((ai ->> 'maxAgeDays')::bigint, 30))
           + public.nft_demand_bps(a.id, p_now, p_exclude);
  return floor(v_anchor::numeric * (10000 + v_bonus) / 10000)::bigint;
end;
$$;

create or replace function public.nft_ai_value_cents(p_artwork uuid, p_now timestamptz default null)
returns bigint
language sql
stable
security definer
set search_path = ''
as $$
  select public.nft_ai_value_excluding(p_artwork, p_now, null);
$$;

create or replace function public.nfts_run_due(p_now timestamptz default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  cfg       jsonb := public.nfts_cfg();
  ai        jsonb := public.nfts_cfg() -> 'ai';
  v_now     timestamptz := coalesce(p_now, public.game_now());
  v_day     timestamptz := ((coalesce(p_now, public.game_now()) at time zone 'Europe/Berlin')::date)::timestamp
                           at time zone 'Europe/Berlin';
  v_house   uuid := public.ledger_system_account('households');
  v_buys    integer;
  v_msgs    integer := 0;
  v_sold    integer := 0;
  v_answers integer := 0;
  v_expired integer;
  v_value   bigint;
  v_name    text;
  v_id      bigint;
  v_cash    bigint;
  a         public.artworks;
  r         record;
  v_trades  integer;
  v_traded  integer := 0;
  v_price   bigint;
begin
  if cfg = '{}'::jsonb or ai is null then
    return jsonb_build_object('skipped', 'no config');
  end if;
  update public.artwork_messages set offer_status = 'expired' where offer_status = 'open' and expires_at <= v_now;
  get diagnostics v_expired = row_count;
  -- purchases from players; trades between collectors have their own cap (ADR-141)
  select count(*) into v_buys from public.artwork_sales s where s.buyer_ai is not null and s.seller_ai is null and s.at >= v_day;

  -- 1. fixed-price listings of players: bought at a good price, else maybe a lowball offer
  for r in select x.id, x.ask_cents from public.artworks x
            where x.ask_cents is not null and x.owner_id is not null
              and not exists (select 1 from public.artwork_auctions au where au.artwork_id = x.id and au.status = 'open')
            order by x.listed_at, x.id limit 100 loop
    select * into a from public.artworks where id = r.id for update skip locked;
    continue when a.id is null or a.ask_cents is distinct from r.ask_cents or a.owner_id is null;
    v_value := public.nft_ai_value_cents(a.id, v_now);
    if a.ask_cents <= v_value then
      continue when v_buys >= (ai ->> 'maxBuysPerDay')::integer or random() * 10000 >= (ai ->> 'buyChanceBps')::integer;
      select x.balance_cents into v_cash from public.ledger_accounts x where x.id = v_house;
      continue when coalesce(v_cash, 0) < a.ask_cents;
      v_name := public.nft_pick('{ai,collectors}', random());
      perform public.nft_sell(a.id, null, v_name, a.ask_cents, 'ai',
                              'art:ai:' || a.id::text || ':' || floor(extract(epoch from v_now))::bigint::text);
      perform public.nft_ai_post(a.id, v_name, 'chat', public.nft_pick('{ai,lines,buy}', random()), null);
      v_buys := v_buys + 1;
      v_sold := v_sold + 1;
    elsif v_msgs < (ai ->> 'maxMessagesPerRun')::integer
          and random() * 10000 < (ai ->> 'listedOfferChanceBps')::integer
          and not exists (select 1 from public.artwork_messages m where m.artwork_id = a.id and m.ai_name is not null
                            and m.offer_status = 'open') then
      v_id := public.nft_ai_post(a.id, public.nft_pick('{ai,collectors}', random()), 'offer',
                                 public.nft_pick('{ai,lines,offer}', random()), public.nft_lowball_cents(v_value, random()));
      perform public.nft_notify_offer(v_id);
      v_msgs := v_msgs + 1;
    end if;
  end loop;

  -- 2. NFTs players keep: now and then a lowball offer
  for r in select x.id from public.artworks x
            where x.owner_id is not null and x.ask_cents is null
              and not exists (select 1 from public.artwork_auctions au where au.artwork_id = x.id and au.status = 'open')
              and not exists (select 1 from public.artwork_messages m where m.artwork_id = x.id and m.ai_name is not null
                                and m.offer_status = 'open')
            order by random() limit greatest(0, (ai ->> 'maxMessagesPerRun')::integer - v_msgs) loop
    continue when random() * 10000 >= (ai ->> 'unlistedOfferChanceBps')::integer;
    v_id := public.nft_ai_post(r.id, public.nft_pick('{ai,collectors}', random()), 'offer',
                               public.nft_pick('{ai,lines,offer}', random()),
                               public.nft_lowball_cents(public.nft_ai_value_cents(r.id, v_now), random()));
    perform public.nft_notify_offer(v_id);
    v_msgs := v_msgs + 1;
  end loop;

  -- 3. NFTs the AI holds: player offers from acceptBps of the value are accepted, others declined
  for r in select m.id, m.artwork_id, m.author_id, m.offer_cents from public.artwork_messages m
             join public.artworks x on x.id = m.artwork_id
            where x.ai_owner is not null and m.offer_status = 'open' and m.author_id is not null
            order by m.id limit 50 loop
    select * into a from public.artworks where id = r.artwork_id for update skip locked;
    continue when a.id is null or a.ai_owner is null;
    v_value := public.nft_ai_value_excluding(a.id, v_now, r.author_id);
    select x.balance_cents into v_cash from public.ledger_accounts x where x.owner_player_id = r.author_id and x.kind = 'player_cash';
    if r.offer_cents::numeric * 10000 >= v_value::numeric * (ai ->> 'acceptBps')::integer and coalesce(v_cash, 0) >= r.offer_cents then
      update public.artwork_messages set offer_status = 'accepted' where id = r.id;
      v_name := a.ai_owner;
      perform public.nft_sell(a.id, r.author_id, null, r.offer_cents, 'offer', 'art:offer:' || r.id::text, r.id);
      perform public.nft_ai_post(a.id, v_name, 'chat', public.nft_pick('{ai,lines,accept}', random()), null);
    else
      update public.artwork_messages set offer_status = 'declined' where id = r.id;
      perform public.nft_ai_post(a.id, a.ai_owner, 'chat', public.nft_pick('{ai,lines,decline}', random()), null);
    end if;
    v_answers := v_answers + 1;
  end loop;

  -- 4. The collectors trade among themselves (ADR-141): popular NFTs change hands more often; the price follows the
  --    buyer's taste around the fair value and moves only part of the way from the last price.
  select count(*) into v_trades from public.artwork_sales s
   where s.seller_ai is not null and s.buyer_ai is not null and s.at >= v_day;
  for r in select x.id, x.ai_owner, x.value_cents,
                  (select count(*) from public.artwork_likes l where l.artwork_id = x.id) as likes,
                  (select count(distinct coalesce(m.author_id::text, m.ai_name)) from public.artwork_messages m
                    where m.artwork_id = x.id and m.offer_status = 'open') as offers,
                  (select count(*) from public.artwork_sales s where s.artwork_id = x.id
                    and s.at >= v_now - make_interval(days => (ai #>> '{demand,days}')::integer)) as sales
             from public.artworks x
            where x.ai_owner is not null and x.owner_id is null
              and coalesce(x.listed_at, x.created_at) <= v_now - make_interval(mins => (ai #>> '{trade,minHoldMinutes}')::integer)
              and not exists (select 1 from public.artwork_auctions au where au.artwork_id = x.id and au.status = 'open')
            order by random() limit 200 loop
    exit when v_traded >= (ai #>> '{trade,perRun}')::integer or v_trades >= (ai #>> '{trade,perDay}')::integer;
    continue when random() * 10000 >= least((ai #>> '{trade,maxChanceBps}')::numeric,
      floor((ai #>> '{trade,chanceBps}')::numeric * (10000 + (ai #>> '{trade,likeWeightBps}')::numeric * r.likes
            + (ai #>> '{trade,offerWeightBps}')::numeric * r.offers + (ai #>> '{trade,saleWeightBps}')::numeric * r.sales) / 10000));
    select * into a from public.artworks where id = r.id for update skip locked;
    continue when a.id is null or a.ai_owner is distinct from r.ai_owner;
    -- the buyer is always another collector
    select c into v_name from jsonb_array_elements_text(ai -> 'collectors') c where c <> a.ai_owner order by random() limit 1;
    continue when v_name is null;
    v_price := public.nft_ai_trade_price_cents(a.value_cents, public.nft_fair_cents(a.id, v_now), random());
    perform public.nft_sell(a.id, null, v_name, v_price, 'ai',
                            'art:trade:' || a.id::text || ':' || floor(extract(epoch from v_now))::bigint::text);
    perform public.nft_ai_post(a.id, v_name, 'chat', public.nft_pick('{ai,lines,trade}', random()), null);
    v_traded := v_traded + 1;
    v_trades := v_trades + 1;
  end loop;

  return jsonb_build_object('sold', v_sold, 'offers', v_msgs, 'answered', v_answers, 'expired', v_expired,
                            'traded', v_traded);
end;
$$;

revoke all on function public.nft_demand_bps(uuid, timestamptz, uuid) from public, anon, authenticated;
revoke all on function public.nft_ai_value_excluding(uuid, timestamptz, uuid) from public, anon, authenticated;
revoke all on function public.nft_fair_cents(uuid, timestamptz) from public, anon, authenticated;
revoke all on function public.nft_ai_trade_price_cents(bigint, bigint, double precision) from public, anon, authenticated;

-- ===== supabase/migrations/20261204001500_mission_xp.sql =====
-- =============================================================================
-- NEXA · 1500 · Missions: more XP at higher levels, and work for another player once (ADR-142)
-- =============================================================================
-- Mission XP grows with the level: x min(missionXpScaleMax, 1 + missionXpScalePerLevel x (level - 1)), set when a
-- mission is handed out (templates with params.fixedXp keep their XP). New milestone m_work_for_player: take a job at
-- another real player's company; it comes before every other milestone (chain 0) once jobs are unlocked. Metric player_job:
-- starting a job at a player company, or every worked hour there (so players who already work for someone get it).
-- Idempotent: runs unchanged as supabase/updates/20261204001500_mission_xp.sql.

create or replace function public.missions_assign(p_player uuid)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_prog     jsonb := coalesce(public.config_jsonb('progression'), '{}'::jsonb);
  v_now      timestamptz := public.game_now();
  v_today    date := (public.game_now() at time zone 'Europe/Berlin')::date;
  v_monday   date;
  v_level    integer;
  v_scale    double precision;
  v_xpscale  double precision;
  v_need     integer;
  v_n        integer := 0;
  v_kind     text;
  v_period   date;
  v_expires  timestamptz;
  v_rank     integer;
  t          record;
begin
  v_monday := v_today - (extract(isodow from v_today)::integer - 1);
  select p.level into v_level from public.profiles p where p.id = p_player for update;
  if v_level is null then
    return 0;
  end if;
  v_scale := least(public.cfg_num(v_prog, '{missionTargetScaleMax}', 5),
                   1 + public.cfg_num(v_prog, '{missionTargetScalePerLevel}', 0.2) * (v_level - 1));
  -- ADR-142: mission XP grows with the level, so missions stay worth it as levels need more XP
  v_xpscale := least(public.cfg_num(v_prog, '{missionXpScaleMax}', 1),
                     1 + public.cfg_num(v_prog, '{missionXpScalePerLevel}', 0) * (v_level - 1));

  -- expire what ran out
  update public.player_missions set status = 'expired'
   where player_id = p_player and status in ('active', 'completed') and expires_at is not null and expires_at <= v_now;

  foreach v_kind in array array['quick', 'daily', 'weekly', 'milestone'] loop
    if v_kind = 'quick' then
      v_need := public.cfg_num(v_prog, '{xpSources,quickMission,active}', 3)::integer
              - (select count(*) from public.player_missions m where m.player_id = p_player and m.kind = 'quick' and m.status in ('active', 'completed'));
      v_period := v_today; v_expires := null;
    elsif v_kind = 'daily' then
      v_need := public.cfg_num(v_prog, '{xpSources,dailyMission,perDay}', 3)::integer
              - (select count(*) from public.player_missions m where m.player_id = p_player and m.kind = 'daily' and m.period_start = v_today);
      v_period := v_today; v_expires := ((v_today + 1)::timestamp) at time zone 'Europe/Berlin';
    elsif v_kind = 'weekly' then
      v_need := public.cfg_num(v_prog, '{xpSources,weeklyMission,perWeek}', 3)::integer
              - (select count(*) from public.player_missions m where m.player_id = p_player and m.kind = 'weekly' and m.period_start = v_monday);
      v_period := v_monday; v_expires := ((v_monday + 7)::timestamp) at time zone 'Europe/Berlin';
    else
      v_need := public.cfg_num(v_prog, '{xpSources,milestoneMission,visible}', 3)::integer
              - (select count(*) from public.player_missions m where m.player_id = p_player and m.kind = 'milestone' and m.status in ('active', 'completed'));
      v_period := date '2000-01-01'; v_expires := null;
    end if;
    continue when v_need <= 0;

    for t in
      select mt.*
        from public.mission_templates mt
       where mt.kind = v_kind and mt.mode is not null and mt.is_active
         and mt.min_level <= v_level
         and (not (mt.params ? 'unlock') or v_level >= public.unlock_level(mt.params ->> 'unlock'))
         and public.mission_requirement_ok(p_player, mt.params ->> 'requires')
         and not exists (select 1 from public.player_missions m
                          where m.player_id = p_player and m.template_key = mt.key
                            and (m.period_start = v_period
                                 or (v_kind = 'quick' and (m.status in ('active', 'completed') or m.created_at > v_now - interval '24 hours'))
                                 or v_kind = 'milestone'))
       order by case when v_kind = 'milestone' then mt.chain_order end,
                -ln(1 - random()) / greatest(mt.weight, 1)
       limit v_need
    loop
      if t.metric = 'rich_rank_improve' then
        v_rank := public.player_rich_rank(p_player);
        continue when v_rank is null or v_rank <= 1;
      end if;
      insert into public.player_missions (player_id, template_key, kind, period_start, target, xp_reward, expires_at, state)
      values (p_player, t.key, v_kind, v_period,
              case when t.scale_with_level and public.mission_is_money_metric(t.metric)
                   then round((t.target_min + floor(random() * (t.target_max - t.target_min + 1))) * v_scale / 100)::bigint * 100
                   else t.target_min + floor(random() * (t.target_max - t.target_min + 1))::bigint end,
              case when coalesce((t.params ->> 'fixedXp')::boolean, false)
                   then t.xp_min + floor(random() * (t.xp_max - t.xp_min + 1))::integer
                   else round((t.xp_min + floor(random() * (t.xp_max - t.xp_min + 1))) * v_xpscale)::integer end,
              v_expires,
              case when t.metric = 'rich_rank_improve' then jsonb_build_object('baseline_rank', v_rank) else '{}'::jsonb end)
      on conflict (player_id, template_key, period_start) do nothing;
      if found then
        v_n := v_n + 1;
      end if;
    end loop;
  end loop;
  if v_n > 0 then
    perform public.mission_refresh_state(p_player);
  end if;
  return v_n;
end;
$$;

create or replace function public.player_job_mission_trigger()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.status = 'active'
     and exists (select 1 from public.player_companies pc
                  where pc.company_id = new.company_id and pc.founder_id <> new.player_id)
     and (tg_op = 'INSERT' or old.status is distinct from new.status
          or new.experience_minutes / 60 > old.experience_minutes / 60) then
    perform public.mission_event(new.player_id, 'player_job', 1, null);
  end if;
  return null;
end;
$$;
comment on function public.player_job_mission_trigger() is
  'Mission event player_job: a job at another real player''s company starts, or an hour is worked there (ADR-142).';
revoke all on function public.player_job_mission_trigger() from public, anon, authenticated;
drop trigger if exists player_job_mission on public.player_jobs;
create trigger player_job_mission
  after insert or update of status, experience_minutes on public.player_jobs
  for each row execute function public.player_job_mission_trigger();

-- 1250 base XP x the global XP multiplier (2) = 2500 XP; fixed, not scaled by level
insert into public.mission_templates
  (key, kind, title, description, icon_key, metric, mode, params, target_min, target_max, xp_min, xp_max, min_level, chain_order,
   scale_with_level, weight, reward_skill_points)
values
  ('m_work_for_player', 'milestone', 'Arbeite bei einem echten Spieler',
   'Bewirb dich bei der Firma eines anderen Spielers und fang dort an. Gemeinsam wächst ihr schneller.', 'mission_job',
   'player_job', 'count', '{"unlock":"first_job","fixedXp":true}'::jsonb, 1, 1, 1250, 1250, 1, 0, false, 100, 1)
on conflict (key) do update
   set kind = excluded.kind, title = excluded.title, description = excluded.description, icon_key = excluded.icon_key,
       metric = excluded.metric, mode = excluded.mode, params = excluded.params, target_min = excluded.target_min,
       target_max = excluded.target_max, xp_min = excluded.xp_min, xp_max = excluded.xp_max, min_level = excluded.min_level,
       chain_order = excluded.chain_order, scale_with_level = excluded.scale_with_level, weight = excluded.weight,
       reward_skill_points = excluded.reward_skill_points, is_active = true, updated_at = now();

-- ===== supabase/migrations/20261204001600_task_games.sql =====
-- =============================================================================
-- NEXA · 1600 · Hands-on task games: slider, rotate, match, path (ADR-144)
-- =============================================================================
-- Four new company task games you drag, turn and draw, like a captcha, solved by looking and thinking:
--   slider  {targets}                  -> {positions}  each piece within tolerance of its gap
--   rotate  {start, target, steps}     -> {dials}      each dial pointing at its mark
--   match   {items, boxes}             -> {boxes}      each card in the box its rule names
--   path    {size, start, goal, walls} -> {path}       shortest route around the walls
-- The solution carries what grading needs (tolerance, steps, the grid), so company_task_grade() stays immutable.
-- Same rules as src/lib/sim/company-tasks.ts. Idempotent: runs unchanged as supabase/updates/20261204001600_task_games.sql.

alter table public.company_tasks drop constraint if exists company_tasks_game_check;
alter table public.company_tasks add constraint company_tasks_game_check
  check (game in ('pick', 'count', 'sort', 'order', 'seq', 'math', 'slider', 'rotate', 'match', 'path'));

-- Moves of the shortest route from p_start to p_goal on a p_size × p_size grid around the walls (breadth-first);
-- null if there is none. Cells are numbered row by row from 0.
create or replace function public.company_task_path_length(p_size integer, p_start integer, p_goal integer,
                                                           p_walls integer[])
returns integer
language plpgsql
immutable
set search_path = ''
as $$
declare
  v_dist  integer[] := array_fill(-1, array[p_size * p_size]);
  v_queue integer[] := array[p_start];
  v_head  integer := 1;
  v_cell  integer;
  v_nb    integer;
  v_r     integer;
  v_c     integer;
begin
  v_dist[p_start + 1] := 0;
  while v_head <= array_length(v_queue, 1) loop
    v_cell := v_queue[v_head];
    v_head := v_head + 1;
    if v_cell = p_goal then
      return v_dist[v_cell + 1];
    end if;
    v_r := v_cell / p_size;
    v_c := v_cell % p_size;
    foreach v_nb in array array[case when v_r > 0 then v_cell - p_size else -1 end,
                                case when v_r < p_size - 1 then v_cell + p_size else -1 end,
                                case when v_c > 0 then v_cell - 1 else -1 end,
                                case when v_c < p_size - 1 then v_cell + 1 else -1 end] loop
      if v_nb >= 0 and v_dist[v_nb + 1] = -1 and not (v_nb = any (coalesce(p_walls, '{}'))) then
        v_dist[v_nb + 1] := v_dist[v_cell + 1] + 1;
        v_queue := v_queue || v_nb;
      end if;
    end loop;
  end loop;
  return null;
end;
$$;

create or replace function public.company_task_puzzle(p_task jsonb)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  g        jsonb := public.company_tasks_cfg() -> 'games' -> (p_task ->> 'game');
  v_game   text := p_task ->> 'game';
  v_n      integer;
  v_tiles  jsonb;
  v_sol    jsonb;
  v_vals   integer[] := '{}';
  v_v      integer;
  a        integer;
  b        integer;
  v_size   integer;
  v_start  integer;
  v_goal   integer;
  v_walls  integer[];
  v_len    integer;
  v_try    integer;
begin
  if v_game in ('pick', 'count') then
    v_n := public.rand_between((g ->> 'minTargets')::integer, (g ->> 'maxTargets')::integer);
    with t as (
      select i, case when i <= v_n then 0 else 1 + floor(random() * 2)::integer end as lab
        from generate_series(1, (g ->> 'tiles')::integer) i),
    s as (select lab, row_number() over (order by random()) - 1 as pos from t)
    select jsonb_agg(lab order by pos), coalesce(jsonb_agg(pos order by pos) filter (where lab = 0), '[]'::jsonb)
      into v_tiles, v_sol from s;
    if v_game = 'pick' then
      return jsonb_build_object('puzzle', jsonb_build_object('tiles', v_tiles), 'solution', jsonb_build_object('targets', v_sol));
    end if;
    return jsonb_build_object('puzzle', jsonb_build_object('tiles', v_tiles), 'solution', jsonb_build_object('count', v_n));
  elsif v_game = 'sort' then
    with s as (select i, row_number() over (order by random()) as pos from generate_series(0, (g ->> 'items')::integer - 1) i)
    select jsonb_agg(i order by pos), jsonb_agg(case when i < (g ->> 'items')::integer / 2 then 0 else 1 end order by pos)
      into v_tiles, v_sol from s;
    return jsonb_build_object('puzzle', jsonb_build_object('items', v_tiles), 'solution', jsonb_build_object('sides', v_sol));
  elsif v_game = 'order' then
    while coalesce(array_length(v_vals, 1), 0) < (g ->> 'items')::integer loop
      -- the task's own realistic range (ADR-140), else the game's default
      v_v := public.rand_between(coalesce((p_task -> 'range' ->> 0)::integer, (g ->> 'min')::integer),
                                 coalesce((p_task -> 'range' ->> 1)::integer, (g ->> 'max')::integer));
      if not v_v = any (v_vals) then
        v_vals := v_vals || v_v;
      end if;
    end loop;
    select jsonb_agg(i - 1 order by case when coalesce((p_task ->> 'asc')::boolean, true) then v else -v end)
      into v_sol from unnest(v_vals) with ordinality as x(v, i);
    return jsonb_build_object('puzzle', jsonb_build_object('values', to_jsonb(v_vals)),
                              'solution', jsonb_build_object('order', v_sol));
  elsif v_game = 'seq' then
    select jsonb_agg(floor(random() * 4)::integer) into v_sol from generate_series(1, (g ->> 'length')::integer);
    return jsonb_build_object('puzzle', jsonb_build_object('sequence', v_sol, 'show_seconds', (g ->> 'showSeconds')::integer),
                              'solution', jsonb_build_object('sequence', v_sol));
  elsif v_game = 'math' then
    a := public.rand_between((p_task -> 'a' ->> 0)::integer, (p_task -> 'a' ->> 1)::integer);
    b := public.rand_between((p_task -> 'b' ->> 0)::integer, (p_task -> 'b' ->> 1)::integer);
    if p_task ->> 'op' = 'pct' then
      -- whole results: big amounts in hundreds, small ones in tens with rates in tens
      if (p_task -> 'a' ->> 1)::integer >= 1000 then
        a := greatest(100, (a / 100) * 100);
      else
        a := greatest(10, (a / 10) * 10);
        b := greatest(10, (b / 10) * 10);
      end if;
    end if;
    v_v := case p_task ->> 'op' when 'mul' then a * b when 'add' then a + b when 'sub' then a - b
                                when 'pct' then a * b / 100 end;
    return jsonb_build_object('puzzle', jsonb_build_object('a', a, 'b', b), 'solution', jsonb_build_object('value', v_v));
  elsif v_game = 'slider' then
    -- ADR-144: one gap per slider on a track of 0..100; the piece starts at 0
    select jsonb_agg(public.rand_between((g ->> 'min')::integer, (g ->> 'max')::integer) order by i)
      into v_sol from generate_series(1, (g ->> 'sliders')::integer) i;
    return jsonb_build_object('puzzle', jsonb_build_object('targets', v_sol),
                              'solution', jsonb_build_object('positions', v_sol, 'tolerance', (g ->> 'tolerance')::integer));
  elsif v_game = 'rotate' then
    -- every dial starts minTurn .. steps - minTurn steps away from its mark
    select jsonb_agg(t order by i),
           jsonb_agg((t + public.rand_between((g ->> 'minTurn')::integer, (g ->> 'steps')::integer - (g ->> 'minTurn')::integer))
                     % (g ->> 'steps')::integer order by i)
      into v_sol, v_tiles
      from (select i, public.rand_between(0, (g ->> 'steps')::integer - 1) as t
              from generate_series(1, (g ->> 'dials')::integer) i) x;
    return jsonb_build_object('puzzle', jsonb_build_object('start', v_tiles, 'target', v_sol, 'steps', (g ->> 'steps')::integer),
                              'solution', jsonb_build_object('dials', v_sol, 'steps', (g ->> 'steps')::integer));
  elsif v_game = 'match' then
    -- perBox of the groupSize cards of every box, shuffled; card i belongs in box i / groupSize
    with c as (
      select bx, k, row_number() over (partition by bx order by random()) as rn
        from generate_series(0, (g ->> 'boxes')::integer - 1) bx, generate_series(0, (g ->> 'groupSize')::integer - 1) k),
    s as (select bx * (g ->> 'groupSize')::integer + k as item, bx, row_number() over (order by random()) as pos
            from c where rn <= (g ->> 'perBox')::integer)
    select jsonb_agg(item order by pos), jsonb_agg(bx order by pos) into v_tiles, v_sol from s;
    return jsonb_build_object('puzzle', jsonb_build_object('items', v_tiles, 'boxes', (g ->> 'boxes')::integer),
                              'solution', jsonb_build_object('boxes', v_sol));
  elsif v_game = 'path' then
    -- start on the left edge, goal on the right; the walls must force a detour of at least minDetour steps
    v_size := (g ->> 'size')::integer;
    for v_try in 1..60 loop
      v_start := public.rand_between(0, v_size - 1) * v_size;
      v_goal := public.rand_between(0, v_size - 1) * v_size + v_size - 1;
      v_n := public.rand_between((g ->> 'minWalls')::integer, (g ->> 'maxWalls')::integer);
      select coalesce(array_agg(c order by c), '{}') into v_walls
        from (select c from generate_series(0, v_size * v_size - 1) c
               where c not in (v_start, v_goal) order by random() limit v_n) x;
      v_len := public.company_task_path_length(v_size, v_start, v_goal, v_walls);
      exit when v_len is not null
            and v_len >= abs(v_start / v_size - v_goal / v_size) + v_size - 1 + (g ->> 'minDetour')::integer;
      v_len := null;
    end loop;
    if v_len is null then
      -- fallback: a wall across the middle column
      v_start := (v_size / 2) * v_size;
      v_goal := v_start + v_size - 1;
      select array_agg(k * v_size + v_size / 2 order by k) into v_walls from generate_series(1, v_size - 2) k;
      v_len := public.company_task_path_length(v_size, v_start, v_goal, v_walls);
    end if;
    return jsonb_build_object(
      'puzzle', jsonb_build_object('size', v_size, 'start', v_start, 'goal', v_goal, 'walls', to_jsonb(v_walls)),
      'solution', jsonb_build_object('size', v_size, 'start', v_start, 'goal', v_goal, 'walls', to_jsonb(v_walls),
                                     'length', v_len, 'step_bps', (g ->> 'stepBps')::integer));
  end if;
  raise exception 'unknown task game %', v_game;
end;
$$;

create or replace function public.company_task_grade(p_game text, p_solution jsonb, p_answer jsonb)
returns integer
language plpgsql
immutable
set search_path = ''
as $$
declare
  v_hits    integer;
  v_wrong   integer;
  v_total   integer;
  v_diff    integer;
  v_key     text;
  v_sum     bigint;
  v_exact   numeric;
  v_half    numeric;
  v_steps   numeric;
  v_size    integer;
  v_route   integer[];
  v_k       integer;
begin
  if p_answer is null or jsonb_typeof(p_answer) <> 'object' then
    return 0;
  end if;
  if p_game = 'pick' then
    if jsonb_typeof(p_answer -> 'picked') <> 'array' then
      return 0;
    end if;
    v_total := jsonb_array_length(p_solution -> 'targets');
    select count(*) filter (where p_solution -> 'targets' @> to_jsonb(x)),
           count(*) filter (where not p_solution -> 'targets' @> to_jsonb(x))
      into v_hits, v_wrong
      from (select distinct x from jsonb_array_elements(p_answer -> 'picked') x) d;
    return greatest(0, least(10000, ((v_hits - v_wrong) * 10000) / greatest(v_total, 1)));
  elsif p_game in ('count', 'math') then
    v_key := case p_game when 'count' then 'count' else 'value' end;
    if jsonb_typeof(p_answer -> v_key) <> 'number' then
      return 0;
    end if;
    v_diff := abs((p_answer ->> v_key)::numeric - (p_solution ->> v_key)::numeric);
    return case when v_diff = 0 then 10000 when p_game = 'count' and v_diff = 1 then 5000 else 0 end;
  elsif p_game in ('slider', 'rotate') then
    -- ADR-144: per piece or dial exact (slider: within the tolerance) full marks, close half; the average counts
    v_key := case p_game when 'slider' then 'positions' else 'dials' end;
    if jsonb_typeof(p_answer -> v_key) <> 'array' then
      return 0;
    end if;
    if p_game = 'slider' then
      v_exact := (p_solution ->> 'tolerance')::numeric;
      v_half := 3 * v_exact;
    else
      v_exact := 0;
      v_half := 1;
      v_steps := (p_solution ->> 'steps')::numeric;
    end if;
    v_total := jsonb_array_length(p_solution -> v_key);
    select coalesce(sum(case when d is null then 0 when d <= v_exact then 10000 when d <= v_half then 5000 else 0 end), 0)
      into v_sum
      from (select case when a.v is null or jsonb_typeof(a.v) <> 'number' then null
                        when p_game = 'slider' then abs((a.v #>> '{}')::numeric - (s.v #>> '{}')::numeric)
                        else least(abs((a.v #>> '{}')::numeric - (s.v #>> '{}')::numeric) % v_steps,
                                   v_steps - abs((a.v #>> '{}')::numeric - (s.v #>> '{}')::numeric) % v_steps)
                   end as d
              from jsonb_array_elements(p_solution -> v_key) with ordinality s(v, i)
              left join jsonb_array_elements(p_answer -> v_key) with ordinality a(v, i) on a.i = s.i) x;
    return (v_sum / greatest(v_total, 1))::integer;
  elsif p_game = 'path' then
    -- a route from start to goal in single steps, around the walls, no cell twice; each extra step costs step_bps
    if jsonb_typeof(p_answer -> 'path') <> 'array' then
      return 0;
    end if;
    v_size := (p_solution ->> 'size')::integer;
    if exists (select 1 from jsonb_array_elements(p_answer -> 'path') e
                where case when jsonb_typeof(e) <> 'number' then true
                           else (e #>> '{}')::numeric % 1 <> 0
                             or (e #>> '{}')::numeric not between 0 and v_size * v_size - 1 end) then
      return 0;
    end if;
    select array_agg((e #>> '{}')::numeric::integer order by i) into v_route
      from jsonb_array_elements(p_answer -> 'path') with ordinality x(e, i);
    v_total := coalesce(array_length(v_route, 1), 0);
    if v_total < 2 or v_route[1] <> (p_solution ->> 'start')::integer
       or v_route[v_total] <> (p_solution ->> 'goal')::integer then
      return 0;
    end if;
    if (select count(distinct c) from unnest(v_route) c) <> v_total
       or exists (select 1 from jsonb_array_elements_text(p_solution -> 'walls') w where w::integer = any (v_route)) then
      return 0;
    end if;
    for v_k in 2..v_total loop
      if abs(v_route[v_k] / v_size - v_route[v_k - 1] / v_size)
         + abs(v_route[v_k] % v_size - v_route[v_k - 1] % v_size) <> 1 then
        return 0;
      end if;
    end loop;
    return greatest(0, least(10000,
      10000 - (v_total - 1 - (p_solution ->> 'length')::integer) * (p_solution ->> 'step_bps')::integer));
  else
    v_key := case p_game when 'sort' then 'sides' when 'order' then 'order' when 'match' then 'boxes' else 'sequence' end;
    if jsonb_typeof(p_answer -> v_key) <> 'array' then
      return 0;
    end if;
    v_total := jsonb_array_length(p_solution -> v_key);
    select count(*) into v_hits
      from jsonb_array_elements(p_solution -> v_key) with ordinality s(v, i)
      join jsonb_array_elements(p_answer -> v_key) with ordinality a(v, i) on a.i = s.i
     where a.v = s.v;
    return (v_hits * 10000) / greatest(v_total, 1);
  end if;
end;
$$;

revoke all on function public.company_task_path_length(integer, integer, integer, integer[]) from public, anon, authenticated;

-- ===== supabase/migrations/20261204001700_market_popularity_ipo.sql =====
-- =============================================================================
-- NEXA · 1700 · Popular stocks first (ADR-145) and a 10-minute IPO (ADR-146)
-- =============================================================================
-- A. Popularity: opening a stock's page counts as a view (record_security_view, once per player and stock within
--    marketPopularity.viewCooldownMinutes, at most maxViewsPerDay a day, the founder's own stock never). Every
--    refreshMinutes the snapshot build recomputes one score per listed stock from the views and investments
--    (distinct buyers and bought euros from trades and subscriptions) of the last windowDays days and stores it in
--    security_popularity. get_market_snapshot() reads it with one join, so the per-tick cache (ADR-123) stays cheap.
--    Port of src/lib/sim/popularity.ts (popularityScore, viewCounts).
-- B. IPO and capital increases: the subscription runs startups.ipo.subscriptionMinutes (10). AI investors subscribe
--    their share (aiTakeShare(quality) of the offer) evenly over the window, paid by the financial market. Once every
--    share is subscribed the offer closes at once and the company is listed; at the end of the window it is listed
--    with what was subscribed, the rest is not issued. Port of aiSubscribedE6 (src/lib/sim/startup.ts).
-- RPCs (authenticated): record_security_view(p_request_id uuid, p_ticker text) -> {"counted": boolean}.
-- Idempotent: runs unchanged as supabase/updates/20261204001700_market_popularity_ipo.sql.

-- ---------------------------------------------------------------------------
-- A. Popularity
-- ---------------------------------------------------------------------------
create table if not exists public.security_view_days (
  security_id uuid not null references public.securities (id) on delete cascade,
  day         date not null,
  views       integer not null default 0 check (views >= 0),
  primary key (security_id, day)
);
alter table public.security_view_days enable row level security;
revoke all on public.security_view_days from public, anon, authenticated;
comment on table public.security_view_days is 'Counted views of stock pages per day (ADR-145). Internal.';

create table if not exists public.security_view_marks (
  player_id   uuid not null references public.profiles (id) on delete cascade,
  security_id uuid not null references public.securities (id) on delete cascade,
  counted_at  timestamptz not null,
  primary key (player_id, security_id)
);
alter table public.security_view_marks enable row level security;
create index if not exists security_view_marks_security_idx on public.security_view_marks (security_id);
revoke all on public.security_view_marks from public, anon, authenticated;
comment on table public.security_view_marks is 'Last counted view per player and stock, for the view cooldown (ADR-145). Internal.';

create table if not exists public.security_popularity (
  security_id  uuid primary key references public.securities (id) on delete cascade,
  views        integer not null default 0,
  investors    integer not null default 0,
  bought_cents bigint not null default 0,
  score        bigint not null default 0,
  refreshed_at timestamptz not null default now()
);
alter table public.security_popularity enable row level security;
revoke all on public.security_popularity from public, anon, authenticated;
comment on table public.security_popularity is 'Popularity score per listed stock, refreshed with the market snapshot (ADR-145). Internal.';

create table if not exists public.market_popularity_state (
  id           boolean primary key default true check (id),
  refreshed_at timestamptz not null
);
alter table public.market_popularity_state enable row level security;
revoke all on public.market_popularity_state from public, anon, authenticated;
comment on table public.market_popularity_state is 'When security_popularity was last recomputed (ADR-145). Internal.';

-- popularityScore: views x view + investors x investor + floor(sqrt(bought euros) x volume)
create or replace function public.security_popularity_score(p_views bigint, p_investors bigint, p_bought_cents bigint)
returns bigint
language sql
stable
security definer
set search_path = ''
as $$
  select (greatest(coalesce(p_views, 0), 0) * public.cfg_num(c.v, '{weights,view}', 1)
          + greatest(coalesce(p_investors, 0), 0) * public.cfg_num(c.v, '{weights,investor}', 20)
          + floor(sqrt(greatest(floor(coalesce(p_bought_cents, 0) / 100.0), 0)) * public.cfg_num(c.v, '{weights,volume}', 0.2)))::bigint
    from (select coalesce(public.config_jsonb('marketPopularity'), '{}'::jsonb) as v) c;
$$;

create or replace function public.record_security_view(p_request_id uuid, p_ticker text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid := public.require_player();
  v_cfg    jsonb := coalesce(public.config_jsonb('marketPopularity'), '{}'::jsonb);
  v_sec    uuid;
  v_hit    boolean;
begin
  if p_request_id is null or p_ticker is null then
    perform public.api_error('invalid_argument');
  end if;
  select s.id into v_sec from public.securities s
   where s.ticker = upper(btrim(p_ticker)) and s.kind = 'stock' and s.status = 'listed';
  -- unknown tickers, bonds and the founder's own stock do not count
  if v_sec is null or exists (select 1 from public.securities s join public.player_companies pc on pc.company_id = s.company_id
                               where s.id = v_sec and pc.founder_id = v_player) then
    return jsonb_build_object('counted', false);
  end if;
  -- naturally idempotent: a repeat within the cooldown changes nothing
  insert into public.security_view_marks as m (player_id, security_id, counted_at)
  values (v_player, v_sec, now())
  on conflict (player_id, security_id) do update set counted_at = excluded.counted_at
   where m.counted_at <= now() - make_interval(mins => public.cfg_num(v_cfg, '{viewCooldownMinutes}', 30)::integer)
  returning true into v_hit;
  if v_hit is null
     or not public.rate_limit_hit(v_player, 'security_view', public.cfg_num(v_cfg, '{maxViewsPerDay}', 200)::integer, 86400) then
    return jsonb_build_object('counted', false);
  end if;
  insert into public.security_view_days as d (security_id, day, views)
  values (v_sec, (now() at time zone 'UTC')::date, 1)
  on conflict (security_id, day) do update set views = d.views + 1;
  return jsonb_build_object('counted', true);
end;
$$;

-- Recomputes security_popularity from the last windowDays days: views, distinct investors (buy trades and
-- subscriptions, the founder excluded) and the euros they put in. One index range scan per listed stock.
create or replace function public.refresh_security_popularity()
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_cfg   jsonb := coalesce(public.config_jsonb('marketPopularity'), '{}'::jsonb);
  v_days  integer := greatest(1, public.cfg_num(v_cfg, '{windowDays}', 3)::integer);
  v_today date := (now() at time zone 'UTC')::date;
  v_since timestamptz := now() - make_interval(days => v_days);
  v_n     integer;
begin
  delete from public.security_view_days where day <= v_today - v_days;
  delete from public.security_view_marks
   where counted_at < now() - make_interval(mins => greatest(public.cfg_num(v_cfg, '{viewCooldownMinutes}', 30)::integer, 1440));
  delete from public.security_popularity p
   where not exists (select 1 from public.securities s where s.id = p.security_id and s.kind = 'stock' and s.status = 'listed');
  insert into public.security_popularity as p (security_id, views, investors, bought_cents, score, refreshed_at)
  select s.id, coalesce(v.views, 0), coalesce(i.investors, 0), coalesce(i.bought, 0),
         public.security_popularity_score(coalesce(v.views, 0), coalesce(i.investors, 0), coalesce(i.bought, 0)), now()
    from public.securities s
    left join public.player_companies pc on pc.company_id = s.company_id
    left join lateral (select sum(d.views)::bigint as views from public.security_view_days d
                        where d.security_id = s.id and d.day > v_today - v_days) v on true
    left join lateral (
      select count(distinct x.player_id)::bigint as investors, coalesce(sum(x.cents), 0)::bigint as bought
        from (select t.player_id, t.gross_cents as cents from public.trades t
               where t.security_id = s.id and t.executed_at > v_since and t.side = 'buy'
              union all
              select os.player_id, os.amount_cents from public.offer_subscriptions os
                join public.company_share_offers o on o.id = os.offer_id
               where o.security_id = s.id and os.created_at > v_since) x
       where x.player_id is distinct from pc.founder_id) i on true
   where s.kind = 'stock' and s.status = 'listed'
   order by s.id
  on conflict (security_id) do update
    set views = excluded.views, investors = excluded.investors, bought_cents = excluded.bought_cents,
        score = excluded.score, refreshed_at = excluded.refreshed_at;
  get diagnostics v_n = row_count;
  insert into public.market_popularity_state (id, refreshed_at) values (true, now())
  on conflict (id) do update set refreshed_at = excluded.refreshed_at;
  return v_n;
end;
$$;

-- The snapshot of ADR-123 plus the popularity score per stock. The score is recomputed with the build of a tick when
-- it is older than refreshMinutes (one caller at a time).
create or replace function public.get_market_snapshot()
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_now     timestamptz := public.game_now();
  v_tick    bigint;
  v_cache   public.market_snapshot_cache;
  v_index   jsonb;
  v_secs    jsonb;
  v_payload jsonb;
  v_pop_at  timestamptz;
begin
  perform public.require_player();
  select coalesce(r.tick_seq, 0) into v_tick from public.sim_runtime r where r.id;
  select * into v_cache from public.market_snapshot_cache c where c.id;
  -- the same tick, and not older than a minute (a paused market still refreshes its economy figures)
  if v_cache.id is not null and v_cache.tick_seq = coalesce(v_tick, 0) and v_cache.built_at > now() - interval '1 minute' then
    return v_cache.payload || jsonb_build_object('server_time', v_now);
  end if;

  select s.refreshed_at into v_pop_at from public.market_popularity_state s where s.id;
  if (v_pop_at is null or v_pop_at <= now() - make_interval(
        mins => public.cfg_num(coalesce(public.config_jsonb('marketPopularity'), '{}'::jsonb), '{refreshMinutes}', 5)::integer))
     and pg_try_advisory_xact_lock(7311045) then
    perform public.refresh_security_popularity();
  end if;

  select jsonb_build_object(
           'ticker', upper(i.key), 'name', s.name, 'value_e4', q.last_price_e4,
           'prev_close_e4', coalesce(q.prev_close_e4, q.last_price_e4), 'change_bps', q.change_bps,
           'day_high_e4', q.day_high_e4, 'day_low_e4', q.day_low_e4)
    into v_index
    from public.indices i
    join public.securities s on s.id = i.security_id
    join public.security_quotes q on q.security_id = s.id
   order by i.created_at
   limit 1;

  select coalesce(jsonb_agg(jsonb_build_object(
           'id', s.id, 'ticker', s.ticker, 'name', s.name, 'kind', s.kind,
           'sector_key', s.sector_key, 'size_class', c.tier,
           'last_price_e4', q.last_price_e4, 'bid_e4', q.bid_e4, 'ask_e4', q.ask_e4,
           'prev_close_e4', coalesce(q.prev_close_e4, q.last_price_e4), 'change_bps', q.change_bps,
           'day_high_e4', coalesce(q.day_high_e4, q.last_price_e4), 'day_low_e4', coalesce(q.day_low_e4, q.last_price_e4),
           'day_volume_e6', q.day_volume_e6, 'market_cap_cents', case when s.kind = 'stock' then q.market_cap_cents end,
           'term_game_years', b.term_game_years, 'coupon_bps', b.coupon_bps,
           'yield_bps', case when s.kind = 'bond' then q.yield_bps end,
           'matures_at', b.matures_at, 'face_value_cents', b.face_value_cents,
           'company_id', s.company_id, 'brand_color', c.brand_color,
           'logo', case when s.company_id is not null then public.company_logo(s.company_id) end,
           'company_kind', case when c.id is not null and not c.is_ai then 'player' else 'ai' end,
           'popularity', case when s.kind = 'stock' then coalesce(pop.score, 0) else 0 end)
         order by case s.kind when 'stock' then 0 else 1 end, sec.sort_order, b.term_game_years, s.ticker), '[]'::jsonb)
    into v_secs
    from public.securities s
    join public.security_quotes q on q.security_id = s.id
    left join public.companies c on c.id = s.company_id
    left join public.sectors sec on sec.key = s.sector_key
    left join public.bonds b on b.security_id = s.id
    left join public.security_popularity pop on pop.security_id = s.id
   where s.status = 'listed' and s.kind in ('stock', 'bond');

  v_payload := jsonb_build_object(
    'tick_seq',        (select r.tick_seq from public.sim_runtime r where r.id),
    'last_tick_at',    (select r.last_tick_at from public.sim_runtime r where r.id),
    'session',         public.market_session_at(v_now),
    'paused',          coalesce((select r.is_paused from public.sim_runtime r where r.id), false),
    'policy_rate_bps', (select cb.policy_rate_bps from public.central_bank_state cb where cb.id),
    'day_start',       public.trading_day_start(v_now),
    'index',           v_index,
    'securities',      v_secs,
    'economy',         jsonb_build_object(
                         'money_supply_cents',      public.money_supply_cents(),
                         'treasury_cents',          public.treasury_balance_cents(),
                         'basic_income_factor_bps', public.basic_income_factor_bps(),
                         'total_supply_cents',      public.config_bigint('money', '{totalSupplyCents}', 1000000000000)));

  insert into public.market_snapshot_cache (id, tick_seq, built_at, payload)
  values (true, coalesce(v_tick, 0), now(), v_payload)
  on conflict (id) do update set tick_seq = excluded.tick_seq, built_at = excluded.built_at, payload = excluded.payload;
  return v_payload || jsonb_build_object('server_time', v_now);
end;
$$;
comment on function public.get_market_snapshot() is
  'RPC: quotes, index, economy and popularity of the latest tick, built once per tick (ADR-123, ADR-145).';

-- ---------------------------------------------------------------------------
-- B. A 10-minute subscription
-- ---------------------------------------------------------------------------
create or replace function public.offer_json(p_offer_id uuid, p_viewer uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'id', o.id,
    'kind', o.kind,
    'company', jsonb_build_object('id', c.id, 'name', c.name, 'color', c.brand_color, 'logo', public.company_logo(c.id),
                                  'sector', c.sector_key, 'product_key', public.company_product(c.id) ->> 'key',
                                  'stage', public.company_stage(c.id)),
    'ticker', c.ticker,
    'price_cents', o.price_cents,
    'shares_offered_e6', o.shares_offered_e6,
    'shares_subscribed_e6', o.shares_subscribed_e6,
    'shares_ai_e6', o.shares_ai_e6,
    'starts_at', o.created_at,
    'ends_at', o.ends_at,
    'status', case when o.status = 'open' and o.ends_at > now() then 'open' else 'closed' end,
    'mine', exists (select 1 from public.player_companies pc where pc.company_id = o.company_id and pc.founder_id = p_viewer),
    'my_shares_e6', coalesce((select sum(s.shares_e6) from public.offer_subscriptions s
                               where s.offer_id = o.id and s.player_id = p_viewer), 0)::bigint,
    'value_cents', public.company_value_cents(c.id),
    'last_quarter', public.company_last_quarter_json(c.id))
    from public.company_share_offers o join public.companies c on c.id = o.company_id
   where o.id = p_offer_id;
$$;

-- aiSubscribedE6: AI investors subscribe aiTakeShare(quality) of the offer evenly over the window (all of it with
-- p_final), never more than players left free; paid by the financial market. Returns the shares (e6) added.
create or replace function public.share_offer_ai_topup(p_offer_id uuid, p_now timestamptz, p_final boolean)
returns bigint
language plpgsql
security definer
set search_path = ''
as $$
declare
  o        public.company_share_offers;
  v_ipo    jsonb := coalesce(public.config_jsonb('startups', '{ipo}'), '{}'::jsonb);
  v_q      double precision;
  v_target bigint;
  v_frac   numeric;
  v_due    bigint;
  v_add    bigint;
  v_pay    bigint;
  v_founder uuid;
begin
  select * into o from public.company_share_offers where id = p_offer_id and status = 'open' for update;
  if o.id is null then
    return 0;
  end if;
  select coalesce(pc.quality, 0), pc.founder_id into v_q, v_founder from public.player_companies pc where pc.company_id = o.company_id;
  v_target := floor(o.shares_offered_e6
                    * least(1, greatest(0, public.cfg_num(v_ipo, '{aiTakeBase}', 0.2)
                                           + public.cfg_num(v_ipo, '{aiTakePerQuality}', 0.5) * coalesce(v_q, 0))))::bigint;
  v_frac := case when p_final or o.ends_at <= o.created_at then 1
                 else least(1, greatest(0, extract(epoch from (coalesce(p_now, now()) - o.created_at))
                                           / extract(epoch from (o.ends_at - o.created_at)))) end;
  v_due := least(floor(v_target * v_frac)::bigint, o.shares_offered_e6 - o.shares_subscribed_e6);
  v_add := v_due - o.shares_ai_e6;
  if v_add <= 0 then
    return 0;
  end if;
  -- telescoping: the payments add up to floor(all AI shares x price) exactly
  v_pay := floor((o.shares_ai_e6 + v_add)::numeric * o.price_cents / 1000000)::bigint
         - floor(o.shares_ai_e6::numeric * o.price_cents / 1000000)::bigint;
  if v_pay > 0 then
    perform public.ledger_transfer(public.ledger_system_account('market'), public.company_cash_account(o.company_id), v_pay,
                                   'transfer', 'Zeichnung durch Investoren', 'share_offer', o.id,
                                   'offer-ai:' || o.id::text || ':' || (o.shares_ai_e6 + v_add)::text, v_founder);
  end if;
  update public.company_share_offers set shares_ai_e6 = shares_ai_e6 + v_add where id = o.id;
  return v_add;
end;
$$;

create or replace function public.go_public(p_request_id uuid, p_share_percent integer)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_company uuid;
  v_player  uuid;
  v_replay  jsonb;
  pc        public.player_companies;
  c         public.companies;
  v_ipo     jsonb := coalesce(public.config_jsonb('startups', '{ipo}'), '{}'::jsonb);
  v_total   bigint;
  v_price   bigint;
  v_level   integer;
  v_minutes integer := greatest(1, public.cfg_num(v_ipo, '{subscriptionMinutes}', 10)::integer);
begin
  v_company := public.require_own_company();
  v_player := public.require_player();
  if p_request_id is null or p_share_percent is null
     or p_share_percent < public.cfg_num(v_ipo, '{minSharePercent}', 10) or p_share_percent > public.cfg_num(v_ipo, '{maxSharePercent}', 49) then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'go_public');
  if v_replay is not null then
    return v_replay;
  end if;
  select * into pc from public.player_companies where company_id = v_company for update;
  select * into c from public.companies where id = v_company;
  if c.phase in ('ipo', 'listed') or public.company_open_offer(v_company) is not null then
    perform public.api_error('already_listed');
  end if;
  select p.level into v_level from public.profiles p where p.id = v_player;
  if v_level < public.cfg_num(v_ipo, '{minLevel}', 6) then
    perform public.api_error('company_level_too_low');
  end if;
  if not (coalesce(v_ipo -> 'fromTiers', '["garage", "small_business", "gmbh"]'::jsonb) ? pc.tier) then
    perform public.api_error('company_upgrade_unavailable');
  end if;
  v_total := public.cfg_num(v_ipo, '{sharesTotal}', 1000000)::bigint * 1000000;
  -- issuePriceCents: company value over all shares, at least minIssuePriceCents
  v_price := greatest(public.cfg_num(v_ipo, '{minIssuePriceCents}', 100)::bigint,
                      round(public.company_value_cents(v_company)::numeric / public.cfg_num(v_ipo, '{sharesTotal}', 1000000)::numeric)::bigint);
  insert into public.company_share_offers (company_id, kind, price_cents, shares_total_e6, shares_offered_e6, request_id, ends_at)
  values (v_company, 'ipo', v_price, v_total, v_total * p_share_percent / 100, p_request_id,
          now() + make_interval(mins => v_minutes));
  update public.companies set phase = 'ipo' where id = v_company;
  perform public.company_system_message(v_company, 'Börsengang: ' || p_share_percent || ' % der Aktien zu '
                                                   || public.format_eur(v_price) || ' je Aktie. Die Zeichnung läuft höchstens '
                                                   || v_minutes || ' Minuten; sind alle Aktien gezeichnet, ist die Firma sofort an der Börse.');
  return public.request_complete(v_player, p_request_id, jsonb_build_object('company', public.company_state(v_company)));
end;
$$;

create or replace function public.capital_increase(p_request_id uuid, p_share_percent integer)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_company uuid;
  v_player  uuid;
  v_replay  jsonb;
  c         public.companies;
  v_ipo     jsonb := coalesce(public.config_jsonb('startups', '{ipo}'), '{}'::jsonb);
  v_price   bigint;
  v_new     bigint;
  v_minutes integer := greatest(1, public.cfg_num(v_ipo, '{subscriptionMinutes}', 10)::integer);
begin
  v_company := public.require_own_company();
  v_player := public.require_player();
  if p_request_id is null or p_share_percent is null or p_share_percent < 1
     or p_share_percent > public.cfg_num(v_ipo, '{capitalIncreaseMaxPercent}', 25) then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'capital_increase');
  if v_replay is not null then
    return v_replay;
  end if;
  select * into c from public.companies where id = v_company for update;
  if c.phase <> 'listed' or c.security_id is null or public.company_open_offer(v_company) is not null then
    perform public.api_error('invalid_argument');
  end if;
  -- capitalIncreasePriceCents: market price x discount, at least minIssuePriceCents
  v_price := greatest(public.cfg_num(v_ipo, '{minIssuePriceCents}', 100)::bigint,
                      round((select q.last_price_e4 from public.security_quotes q where q.security_id = c.security_id) / 100.0
                            * public.cfg_num(v_ipo, '{capitalIncreaseDiscount}', 0.9))::bigint);
  v_new := c.shares_outstanding * 1000000 * p_share_percent / 100;
  insert into public.company_share_offers (company_id, kind, price_cents, shares_total_e6, shares_offered_e6, security_id,
                                           request_id, ends_at)
  values (v_company, 'capital_increase', v_price, c.shares_outstanding * 1000000 + v_new, v_new, c.security_id, p_request_id,
          now() + make_interval(mins => v_minutes));
  perform public.company_system_message(v_company, 'Kapitalerhöhung: neue Aktien zu ' || public.format_eur(v_price)
                                                   || ' je Aktie, die Zeichnung läuft höchstens ' || v_minutes || ' Minuten.');
  return public.request_complete(v_player, p_request_id, jsonb_build_object('company', public.company_state(v_company)));
end;
$$;

-- One tap: the amount buys as many shares as are left. The subscription that fills the offer lists the company.
create or replace function public.subscribe_offer(p_request_id uuid, p_offer_id uuid, p_amount_cents bigint)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_replay jsonb;
  o        public.company_share_offers;
  v_shares bigint;
  v_cost   bigint;
  v_cash   bigint;
  v_full   boolean := false;
begin
  v_player := public.require_player();
  if p_request_id is null or p_amount_cents is null or p_amount_cents < 1 then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'subscribe_offer');
  if v_replay is not null then
    return v_replay;
  end if;
  select * into o from public.company_share_offers where id = p_offer_id for update;
  if o.id is null then
    perform public.api_error('invalid_argument');
  end if;
  if o.status <> 'open' or o.ends_at <= now() then
    perform public.api_error('offer_closed');
  end if;
  if exists (select 1 from public.player_companies pc where pc.company_id = o.company_id and pc.founder_id = v_player) then
    perform public.api_error('invalid_argument');
  end if;
  if o.shares_offered_e6 - o.shares_subscribed_e6 - o.shares_ai_e6 <= 0 then
    perform public.api_error('offer_sold_out');
  end if;
  v_shares := least(floor(p_amount_cents::numeric * 1000000 / o.price_cents)::bigint,
                    o.shares_offered_e6 - o.shares_subscribed_e6 - o.shares_ai_e6);
  if v_shares <= 0 then
    perform public.api_error('invalid_argument');
  end if;
  v_cost := ceil(v_shares::numeric * o.price_cents / 1000000)::bigint;
  perform public.lock_player_accounts(v_player);
  select a.balance_cents into v_cash from public.ledger_accounts a where a.owner_player_id = v_player and a.kind = 'player_cash';
  if coalesce(v_cash, 0) < v_cost then
    perform public.api_error('insufficient_funds');
  end if;
  perform public.ledger_transfer(public.ledger_player_account(v_player, 'player_cash'), public.company_cash_account(o.company_id),
                                 v_cost, 'transfer', 'Zeichnung von Aktien', 'share_offer', o.id,
                                 'subscribe:' || p_request_id::text, v_player);
  insert into public.offer_subscriptions (offer_id, player_id, shares_e6, amount_cents) values (o.id, v_player, v_shares, v_cost);
  update public.company_share_offers set shares_subscribed_e6 = shares_subscribed_e6 + v_shares where id = o.id
  returning shares_subscribed_e6 + shares_ai_e6 >= shares_offered_e6 into v_full;
  -- every share is taken: listed at once (ADR-146)
  if v_full then
    perform public.close_share_offer(o.id);
  end if;
  return public.request_complete(v_player, p_request_id, jsonb_build_object(
    'shares_e6', v_shares, 'amount_cents', v_cost, 'completed', v_full, 'offer', public.offer_json(o.id, v_player)));
end;
$$;

-- End of a subscription (full, or the window is over): AI investors get the rest of their share, the shares are
-- delivered, an IPO lists the company. What nobody subscribed is not issued.
create or replace function public.close_share_offer(p_offer_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  o        public.company_share_offers;
  c        public.companies;
  pc       public.player_companies;
  v_ai     bigint;
  v_issued bigint;
  v_sec    uuid;
  v_ticker text;
  v_price4 bigint;
  v_shares bigint;
  v_half   bigint;
  s        record;
begin
  perform 1 from public.company_share_offers where id = p_offer_id and status = 'open' for update;
  if not found then
    return null;
  end if;
  perform public.share_offer_ai_topup(p_offer_id, now(), true);
  select * into o from public.company_share_offers where id = p_offer_id;
  select * into c from public.companies where id = o.company_id for update;
  select * into pc from public.player_companies where company_id = o.company_id;
  v_price4 := o.price_cents * 100;
  v_ai := o.shares_ai_e6;
  v_issued := o.shares_subscribed_e6 + v_ai;

  if o.kind = 'ipo' then
    v_shares := (o.shares_total_e6 - o.shares_offered_e6 + v_issued) / 1000000;
    v_ticker := public.company_make_ticker(c.name);
    insert into public.securities (kind, ticker, name, company_id, sector_key, status, listed_at)
    values ('stock', v_ticker, c.name, c.id, c.sector_key, 'listed', now())
    returning id into v_sec;
    v_half := greatest(1, v_price4 / 200);
    insert into public.security_quotes (security_id, last_price_e4, bid_e4, ask_e4, prev_close_e4, day_open_e4, day_high_e4, day_low_e4,
                                        market_cap_cents)
    values (v_sec, v_price4, greatest(1, v_price4 - v_half), v_price4 + v_half, v_price4, v_price4, v_price4, v_price4,
            v_shares * o.price_cents);
    insert into public.security_sim_state (security_id, fair_value_e4, ema_fast, ema_slow)
    values (v_sec, greatest(1, public.company_value_cents(c.id) * 100 / greatest(v_shares, 1)), v_price4, v_price4);
    update public.companies
       set security_id = v_sec, ticker = v_ticker, tier = 'penny', phase = 'listed', listed_at = now(), shares_outstanding = greatest(v_shares, 1),
           legal_form = 'ag', max_employees = (public.company_tier_cfg('ag') ->> 'maxEmployees')::integer
     where id = c.id;
    update public.player_companies set tier = 'ag' where company_id = c.id;
    -- the founder keeps everything that was not offered (cost basis 0)
    perform public.grant_position(pc.founder_id, v_sec, o.shares_total_e6 - o.shares_offered_e6, 0);
  else
    v_sec := c.security_id;
    update public.companies set shares_outstanding = (c.shares_outstanding * 1000000 + v_issued) / 1000000 where id = c.id;
  end if;
  for s in select x.player_id, sum(x.shares_e6)::bigint as q from public.offer_subscriptions x
            where x.offer_id = o.id group by x.player_id order by x.player_id loop
    perform public.grant_position(s.player_id, v_sec, s.q, v_price4);
  end loop;
  update public.company_share_offers
     set status = 'closed', closed_at = now(), security_id = v_sec
   where id = o.id;
  perform public.company_system_message(c.id,
    case when o.kind = 'ipo' then 'Börsengang abgeschlossen: ' || v_ticker || ' ist an der Börse.'
         else 'Kapitalerhöhung abgeschlossen.' end);
  return jsonb_build_object('offer_id', o.id, 'issued_e6', v_issued, 'ai_e6', v_ai, 'security_id', v_sec);
end;
$$;

-- Every minute (run_due_part): AI investors subscribe their share of the time passed; full or due offers close.
create or replace function public.close_due_offers(p_now timestamptz default null)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  r     record;
  v_now timestamptz := coalesce(p_now, now());
  v_n   integer := 0;
begin
  for r in select o.id, o.ends_at <= v_now as due from public.company_share_offers o
            where o.status = 'open' order by o.ends_at, o.id loop
    if not r.due then
      perform public.share_offer_ai_topup(r.id, v_now, false);
    end if;
    if r.due or exists (select 1 from public.company_share_offers o
                         where o.id = r.id and o.shares_subscribed_e6 + o.shares_ai_e6 >= o.shares_offered_e6) then
      perform public.close_share_offer(r.id);
      v_n := v_n + 1;
    end if;
  end loop;
  return v_n;
end;
$$;

-- ---------------------------------------------------------------------------
-- Grants
-- ---------------------------------------------------------------------------
do $$
declare
  f text;
begin
  foreach f in array array[
    'public.security_popularity_score(bigint, bigint, bigint)', 'public.record_security_view(uuid, text)',
    'public.refresh_security_popularity()', 'public.share_offer_ai_topup(uuid, timestamptz, boolean)',
    'public.offer_json(uuid, uuid)', 'public.go_public(uuid, integer)', 'public.capital_increase(uuid, integer)',
    'public.subscribe_offer(uuid, uuid, bigint)', 'public.close_share_offer(uuid)', 'public.close_due_offers(timestamptz)'
  ] loop
    execute format('revoke all on function %s from public, anon, authenticated', f);
    execute format('grant execute on function %s to service_role', f);
  end loop;
  foreach f in array array[
    'public.record_security_view(uuid, text)', 'public.go_public(uuid, integer)', 'public.capital_increase(uuid, integer)',
    'public.subscribe_offer(uuid, uuid, bigint)'
  ] loop
    execute format('grant execute on function %s to authenticated', f);
  end loop;
end;
$$;
revoke all on function public.get_market_snapshot() from public, anon;
grant execute on function public.get_market_snapshot() to authenticated, service_role;
comment on function public.record_security_view(uuid, text) is
  'RPC: counts a view of a stock page for the popularity ranking, once per player and stock within the cooldown (ADR-145).';

-- ===== supabase/migrations/20261204001800_task_momentum.sql =====
-- =============================================================================
-- NEXA · 1800 · Solved tasks compound company profit: task momentum (ADR-148)
-- =============================================================================
-- Every solved company task lifts the company's "Schwung" (task_momentum), a demand multiplier on top of everything
-- else. Perfect runs and human work lift it more; a failed or missed task lowers it. It drifts back toward 1 every
-- hour (momentum.decayPerHourBps), so a company only keeps high earnings by keeping the tasks solved. Higher demand
-- means more revenue, which funds upgrades and more staff, which solve more tasks -- so good play compounds.
-- Idempotent: runs unchanged as supabase/updates/20261204001800_task_momentum.sql.

alter table public.player_companies add column if not exists task_momentum double precision not null default 1
  check (task_momentum >= 1);
comment on column public.player_companies.task_momentum is
  'Demand multiplier from solved tasks (ADR-148); lifted on success, lowered on failure, drifts toward 1 each hour.';

create or replace function public.company_task_momentum_apply(p_company uuid, p_score integer, p_by_ai boolean)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  m     jsonb := coalesce(public.company_tasks_cfg() -> 'momentum', '{}'::jsonb);
  v_now double precision;
  v_delta double precision;
begin
  if (m ->> 'maxBps') is null then
    return;  -- momentum not configured
  end if;
  if p_score is not null and p_score >= (public.company_tasks_cfg() ->> 'passScoreBps')::integer then
    -- the gain scales with the score; perfect runs add a bonus; the AI lifts it less than a person
    v_delta := coalesce((m ->> 'perSolveBps')::numeric, 0) * p_score / 10000.0
             + case when p_score >= 10000 then coalesce((m ->> 'perfectBonusBps')::numeric, 0) else 0 end;
    if p_by_ai then
      v_delta := v_delta * coalesce((m ->> 'aiBps')::numeric, 5000) / 10000.0;
    end if;
  else
    v_delta := -coalesce((m ->> 'penaltyBps')::numeric, 0);  -- failed or missed
  end if;
  select coalesce(task_momentum, 1.0) into v_now from public.player_companies where company_id = p_company for update;
  update public.player_companies
     set task_momentum = least(1.0 + coalesce((m ->> 'maxBps')::numeric, 0) / 10000.0,
                               greatest(1.0, v_now + v_delta / 10000.0))
   where company_id = p_company;
end;
$$;
revoke all on function public.company_task_momentum_apply(uuid, integer, boolean) from public, anon, authenticated;
comment on function public.company_task_momentum_apply(uuid, integer, boolean) is
  'Internal: a resolved task lifts or lowers the company''s task_momentum (ADR-148).';

create or replace function public.company_task_resolve(p_task_id bigint, p_score integer, p_by_ai boolean)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  cfg       jsonb := public.company_tasks_cfg();
  t         public.company_tasks;
  v_ok      boolean;
  v_amount  bigint := 0;
  v_avail   bigint;
  v_status  text;
  v_xp      integer := 0;
  v_nick    text;
begin
  select * into t from public.company_tasks where id = p_task_id for update;
  if t.id is null or t.status in ('success', 'failure', 'missed') then
    return null;
  end if;
  v_ok := p_score is not null and p_score >= (cfg ->> 'passScoreBps')::integer;
  if v_ok then
    v_amount := (t.value_cents * p_score) / 10000;
    if p_by_ai then
      v_amount := (v_amount * (cfg -> 'ai' ->> 'valueBps')::integer) / 10000;
    end if;
    -- ADR-134 task_pay of the founder
    v_amount := v_amount + public.apply_bps(v_amount, public.company_upgrade_bps(t.company_id, 'task_pay'));
    select a.balance_cents into v_avail from public.ledger_accounts a
     where a.id = public.ledger_system_account('households') for update;
    v_amount := least(v_amount, greatest(coalesce(v_avail, 0), 0));
    if v_amount > 0 then
      perform public.ledger_transfer(public.ledger_system_account('households'), public.company_cash_account(t.company_id),
                                     v_amount, 'company_revenue', 'Aufgabe erledigt: ' || t.task_key, 'company', t.company_id,
                                     'task:result:' || t.id::text, t.done_by, jsonb_build_object('task', t.task_key));
    end if;
    v_status := 'success';
  else
    v_amount := (t.value_cents * (cfg ->> 'penaltyBps')::integer) / 10000;
    -- ADR-134 task_safety of the founder
    v_amount := v_amount - public.apply_bps(v_amount, public.company_upgrade_bps(t.company_id, 'task_safety'));
    select a.balance_cents into v_avail from public.ledger_accounts a
     where a.id = public.company_cash_account(t.company_id) for update;
    v_amount := least(v_amount, greatest(coalesce(v_avail, 0), 0));
    if v_amount > 0 then
      perform public.ledger_transfer(public.company_cash_account(t.company_id), public.ledger_system_account('households'),
                                     v_amount, 'company_costs', 'Aufgabe verpatzt: ' || t.task_key, 'company', t.company_id,
                                     'task:result:' || t.id::text, t.done_by, jsonb_build_object('task', t.task_key));
    end if;
    v_status := case when p_score is null then 'missed' else 'failure' end;
    v_amount := -v_amount;
  end if;
  -- task momentum (ADR-148): every resolved task moves the company's long-term demand
  perform public.company_task_momentum_apply(t.company_id, p_score, p_by_ai);

  -- missions (ADR-130): done right, done perfectly
  if v_ok and t.done_by is not null and not p_by_ai then
    perform public.mission_event(t.done_by, 'task_done', 1, t.id::text);
    if p_score >= 10000 then
      perform public.mission_event(t.done_by, 'task_perfect', 1, t.id::text);
    end if;
  end if;
  if t.done_by is not null and not p_by_ai then
    v_xp := public.grant_xp(t.done_by, 'work_task',
                            case when v_ok then (cfg -> 'xp' ->> 'success')::integer else (cfg -> 'xp' ->> 'failure')::integer end,
                            'company_task:' || t.id::text, 'company_task', null);
  end if;
  update public.company_tasks
     set status = v_status, score_bps = p_score, result_cents = v_amount, resolved_at = public.game_now()
   where id = t.id;
  select p.nickname into v_nick from public.profiles p where p.id = coalesce(t.done_by, t.assignee_id);
  perform public.company_news_add(t.company_id, 'task_' || v_status,
    jsonb_build_object('task', t.task_key, 'amount_cents', v_amount, 'nickname', v_nick, 'ai', p_by_ai));
  return jsonb_build_object('status', v_status, 'score_bps', p_score, 'result_cents', v_amount, 'xp', v_xp);
end;
$$;

create or replace function public.player_company_close_hour(p_company uuid, p_hour_start timestamptz)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  pc        public.player_companies;
  v_momentum double precision;
  c         public.companies;
  v_su      jsonb := coalesce(public.config_jsonb('startups'), '{}'::jsonb);
  v_hours   double precision := greatest(1, public.config_double('time', '{quarterHours}', 6));
  v_start   timestamptz := date_trunc('hour', p_hour_start);
  v_end     timestamptz;
  v_qid     bigint;
  v_team    jsonb;
  v_price   jsonb;
  v_ev      jsonb;
  v_camp    public.company_campaigns;
  v_stage   integer;
  v_demand  double precision;
  v_cap     double precision;
  v_sold    double precision;
  v_ctr     double precision;
  v_own     bigint;
  v_crev    bigint;
  v_hhbal   bigint;
  v_rev     bigint;
  v_cogs    bigint;
  v_gross   bigint;
  v_aidue   bigint;
  v_aipaid  bigint;
  v_pdue    bigint := 0;
  v_ppaid   bigint := 0;
  v_due     bigint;
  v_factor  integer;
  v_fixed   bigint;
  v_mk      bigint;
  v_costs   bigint;
  v_paid    bigint := 0;
  v_unpaid  bigint := 0;
  v_settle  bigint := 0;
  v_cash    bigint;
  v_acc     uuid;
  v_hh      uuid;
  v_profit  bigint;
  v_owed    bigint;
  v_free    bigint;
  v_stakes  bigint := 0;
  v_sp      bigint;
  v_payout  bigint := 0;
  v_bps     integer;
  v_until   timestamptz;
  v_news    bigint;
  k         text;
  j         record;
  s         record;
begin
  if p_company is null or p_hour_start is null then
    return null;
  end if;
  select * into pc from public.player_companies where company_id = p_company and status = 'active' for update;
  if pc.company_id is null then
    return null;
  end if;
  -- task momentum (ADR-148): solved tasks lift demand; it drifts back toward 1 every hour, so it must be kept up
  v_momentum := greatest(1.0, 1.0 + (coalesce(pc.task_momentum, 1.0) - 1.0)
                  * (1.0 - public.cfg_num(public.company_tasks_cfg(), '{momentum,decayPerHourBps}', 300) / 10000.0));
  if v_momentum <> coalesce(pc.task_momentum, 1.0) then
    update public.player_companies set task_momentum = v_momentum where company_id = p_company;
    pc.task_momentum := v_momentum;
  end if;
  if exists (select 1 from public.player_company_hours h where h.company_id = p_company and h.hour_start = v_start) then
    update public.player_companies set last_hour_at = greatest(last_hour_at, v_start + interval '1 hour')
     where company_id = p_company and last_hour_at < v_start + interval '1 hour';
    return jsonb_build_object('company_id', p_company, 'hour_start', v_start, 'skipped', 'already_closed');
  end if;
  v_end := v_start + interval '1 hour';
  select * into c from public.companies where id = p_company;
  select gq.id into v_qid from public.game_quarters gq where gq.starts_at <= v_start and gq.ends_at > v_start;
  v_team := public.player_company_team(p_company);
  v_acc := public.company_cash_account(p_company);
  v_hh := public.ledger_system_account('households');
  k := 'pch:' || p_company::text || ':' || to_char(v_start at time zone 'UTC', 'YYYYMMDDHH24');
  -- company event of this hour (ADR-091): demand and capacity factors, extra costs as a share of the own revenue
  v_ev := public.company_event_hour_effect(p_company, v_start, v_end);
  -- marketing campaign (ADR-097, campaignDemandFactor): its factor when the hour starts inside its window
  v_camp := public.company_campaign_at(p_company, v_start);

  -- sales of the hour with the quarter's awareness and quality; demand and capacity count in units at the
  -- normal price, the price strategy changes both price and demand (ADR-083)
  v_price := public.company_price_effect(pc.price_level, pc.quality);
  v_stage := least(greatest(coalesce((v_team ->> 'stage')::integer, 0), 0),
                   greatest(jsonb_array_length(coalesce(v_su #> '{stages,awarenessCaps}', '[1]'::jsonb)) - 1, 0));
  v_demand := pc.potential_annual_cents * public.company_market_factor(pc.tier, pc.expansion_level) / 4.0 / v_hours
            * pc.awareness * (0.5 + 0.5 * pc.quality)
            * exp(public.cfg_num(v_su, '{demandNoise}', 0.1) * public.gauss_random())
            * (v_price ->> 'demand')::double precision
            * (v_ev ->> 'demand_factor')::double precision
            * greatest(0, coalesce(v_camp.demand_factor, 1))
            * coalesce(pc.task_momentum, 1.0);
  v_cap := (v_team ->> 'team_productivity_bps')::double precision / 10000.0
         * public.cfg_num(v_su, array['capacityCentsPerProductivity', c.sector_key], 250000)
         * (1 + public.cfg_num(v_su, '{stages,capacityBonusPerStage}', 0.25) * v_stage)
         * public.company_capacity_factor(pc.expansion_level)
         * (v_ev ->> 'capacity_factor')::double precision / v_hours;
  v_sold := least(v_demand, v_cap);
  -- contract work: a share of the unused capacity at the normal price (ADR-083)
  v_ctr := case when pc.contract_work
                then greatest(0, v_cap - v_sold) * public.cfg_num(v_su, '{contractWork,shareOfFreeCapacity}', 0.25)
                else 0 end;
  v_own := round((v_sold * (v_price ->> 'price')::double precision)::numeric)::bigint;
  v_crev := round(v_ctr::numeric)::bigint;
  -- closed money system: the households pay at most what they have (own sales first)
  v_hhbal := greatest(0, coalesce((select a.balance_cents from public.ledger_accounts a where a.id = v_hh), 0));
  if v_own + v_crev > v_hhbal then
    v_own := least(v_own, v_hhbal);
    v_crev := least(v_crev, v_hhbal - v_own);
    v_sold := least(v_sold, v_own / greatest((v_price ->> 'price')::double precision, 0.0001));
    v_ctr := v_crev;
  end if;
  v_rev := v_own + v_crev;
  -- goods; an event's extra costs (or savings) move with the own revenue, goods never cost less than nothing
  v_cogs := round(greatest(0, v_sold * (1 - public.cfg_num(v_su, array['grossMargin', c.sector_key], 0.5))
                              + v_own * (v_ev ->> 'extra_cost_share')::double precision)::numeric)::bigint
          + round((v_ctr * (1 - public.cfg_num(v_su, '{contractWork,grossMargin}', 0.3)))::numeric)::bigint;
  v_gross := v_rev - v_cogs;

  -- presence (ADR-103): employees away for careers.inactivity.fireAfterHours lose the job first, paid up to that moment
  for j in select pj.id from public.player_jobs pj where pj.company_id = p_company and pj.status = 'active' order by pj.id loop
    perform public.job_absence_check(j.id, v_end);
  end loop;
  -- wages due: AI workers and the hourly contract wages of the players (the founder draws no wage)
  v_aidue := pc.ai_workers * public.config_bigint('startups', '{aiWorkerWageCentsPerHour}', 12000);
  for j in select pj.id, pj.salary_cents_per_hour, pj.notice_ends_at from public.player_jobs pj
            where pj.company_id = p_company and pj.status = 'active' order by pj.id loop
    v_until := least(v_end, coalesce(j.notice_ends_at, v_end));
    v_pdue := v_pdue + j.salary_cents_per_hour * public.job_payable_minutes(j.id, v_until) / 60;
  end loop;
  v_due := v_aidue + v_pdue;
  -- never more than the hour earned; everyone gets the same share (ADR-072)
  v_factor := case when v_due <= 0 then 10000 else least(10000, greatest(0, v_gross) * 10000 / v_due)::integer end;
  v_aipaid := v_aidue * v_factor / 10000;

  -- money: revenue (own sales and contract work) from the households, goods and AI wages back to them
  if v_rev > 0 then
    perform public.ledger_transfer(v_hh, v_acc, v_rev, 'company_revenue',
                                   'Umsatz ' || to_char(v_start at time zone 'Europe/Berlin', 'HH24') || ' Uhr',
                                   'company', p_company, k || ':revenue', pc.founder_id);
  end if;
  if v_cogs + v_aipaid > 0 then
    perform public.ledger_transfer(v_acc, v_hh, v_cogs + v_aipaid, 'company_costs', 'Wareneinsatz und KI-Kräfte',
                                   'company', p_company, k || ':goods', pc.founder_id);
  end if;
  -- players: the hour (up to the end of a notice) at contract wage x factor, with XP and branch minutes
  update public.player_companies set pay_factor_bps = v_factor where company_id = p_company;
  for j in select pj.id, pj.player_id, pj.notice_ends_at from public.player_jobs pj
            where pj.company_id = p_company and pj.status = 'active' order by pj.id loop
    v_until := least(v_end, coalesce(j.notice_ends_at, v_end));
    perform public.lock_player_accounts(j.player_id);
    v_ppaid := v_ppaid + public.accrue_job_salary(j.id, v_until);
  end loop;

  -- fixed costs (with the expansion level) and marketing from the cash; the rest becomes an open bill
  -- efficiency upgrade of the founder (ADR-100): the hour's fixed costs x (10 000 − fixedCostDiscountBps) / 10 000
  v_fixed := public.apply_bps(round((public.company_fixed_cost_cents(pc.tier, pc.expansion_level) / v_hours)::numeric)::bigint,
                              10000 - public.player_fixed_cost_discount_bps(pc.founder_id));
  v_mk := round((pc.marketing_cents_per_quarter / v_hours)::numeric)::bigint;
  v_costs := v_fixed + v_mk;
  select greatest(0, a.balance_cents) into v_cash from public.ledger_accounts a where a.id = v_acc;
  v_paid := least(v_costs, coalesce(v_cash, 0));
  if v_paid > 0 then
    perform public.ledger_transfer(v_acc, v_hh, v_paid, 'company_costs', 'Fixkosten und Marketing',
                                   'company', p_company, k || ':costs', pc.founder_id);
  end if;
  v_unpaid := v_costs - v_paid;
  if v_unpaid = 0 and pc.unpaid_cents > 0 then
    select greatest(0, a.balance_cents) into v_cash from public.ledger_accounts a where a.id = v_acc;
    v_settle := least(pc.unpaid_cents, coalesce(v_cash, 0));
    if v_settle > 0 then
      perform public.ledger_transfer(v_acc, v_hh, v_settle, 'company_costs', 'Offene Rechnungen',
                                     'company', p_company, k || ':settle', pc.founder_id);
    end if;
  end if;

  v_profit := v_rev - v_cogs - v_ppaid - v_aipaid - v_fixed - v_mk;
  v_owed := pc.unpaid_cents + v_unpaid - v_settle;

  -- stakes (ADR-098, stakePayoutCents): every running stake whose term holds this hour takes its share of a
  -- profitable hour (rounded down), never more than the free cash; served before the CEO payout. The hour is marked
  -- as handled (settled_until) whether it paid or not.
  for s in select x.id, x.investor_id, x.share_bps from public.deals x
            where x.kind = 'stake' and x.status = 'active' and x.company_id = p_company
              and x.settled_until <= v_start and x.ends_at > v_start
            order by x.accepted_at, x.id for update of x
  loop
    v_sp := 0;
    if v_profit > 0 then
      select a.balance_cents - v_owed into v_free from public.ledger_accounts a where a.id = v_acc;
      v_sp := least(v_profit * s.share_bps / 10000, greatest(0, coalesce(v_free, 0)));
    end if;
    if v_sp > 0 then
      perform public.lock_player_accounts(s.investor_id);
      perform public.ledger_transfer(v_acc, public.ledger_player_account(s.investor_id, 'player_cash'), v_sp, 'dividend',
                                     'Gewinnanteil ' || c.name || ' ' || to_char(v_start at time zone 'Europe/Berlin', 'HH24') || ' Uhr',
                                     'deal', s.id, k || ':stake:' || s.id::text, s.investor_id);
      perform public.loan_withhold(s.investor_id, v_sp, k || ':stake:' || s.id::text);
      v_stakes := v_stakes + v_sp;
    end if;
    update public.deals set payouts_cents = payouts_cents + v_sp, settled_until = v_end where id = s.id;
  end loop;

  -- automatic CEO payout (ADR-086, founderPayoutCents): after the hour's own bookings and the stakes, a share of the
  -- profit left after the stake payouts (rounded down) moves from the company cash to the founder's private cash like
  -- company_withdraw, never more than the free cash. A transfer, not a cost: profit_cents stays as computed above.
  v_bps := least(10000, greatest(0, coalesce(pc.founder_payout_bps, 0)));
  if v_profit - v_stakes > 0 and v_bps > 0 then
    select a.balance_cents - v_owed into v_free from public.ledger_accounts a where a.id = v_acc;
    v_payout := least((v_profit - v_stakes) * v_bps / 10000, greatest(0, coalesce(v_free, 0)));
  end if;
  if v_payout > 0 then
    perform public.lock_player_accounts(pc.founder_id);
    perform public.ledger_transfer(v_acc, public.ledger_player_account(pc.founder_id, 'player_cash'), v_payout, 'transfer',
                                   'CEO-Auszahlung ' || to_char(v_start at time zone 'Europe/Berlin', 'HH24') || ' Uhr',
                                   'company', p_company, k || ':payout', pc.founder_id);
    perform public.loan_withhold(pc.founder_id, v_payout, k || ':payout');
  end if;

  -- record hour (ADR-091): beating an earlier best hour is news, at most one item per Berlin day (updated while the
  -- day's record keeps rising and no AI text was written for it)
  if v_profit > coalesce(pc.best_hour_profit_cents, 0) and coalesce(pc.best_hour_profit_cents, 0) > 0 then
    select n.id into v_news from public.company_news n
     where n.company_id = p_company and n.kind = 'record_hour'
       and ((n.payload ->> 'hour_start')::timestamptz at time zone 'Europe/Berlin')::date
           = (v_start at time zone 'Europe/Berlin')::date
     order by n.id desc limit 1;
    if v_news is null then
      perform public.company_news_add(p_company, 'record_hour',
                                      jsonb_build_object('profit_cents', v_profit, 'hour_start', v_start));
    else
      update public.company_news set payload = jsonb_build_object('profit_cents', v_profit, 'hour_start', v_start)
       where id = v_news and ai_headline is null;
    end if;
  end if;

  update public.player_companies
     set unpaid_cents = v_owed,
         distress = v_owed > 0,
         last_hour_at = greatest(pc.last_hour_at, v_end),
         best_hour_profit_cents = greatest(best_hour_profit_cents, v_profit)
   where company_id = p_company;
  insert into public.player_company_hours (company_id, hour_start, game_quarter_id, demand_cents, capacity_cents, revenue_cents,
                                           contract_revenue_cents, cogs_cents, fixed_cents, marketing_cents, player_wages_due_cents,
                                           player_wages_paid_cents, ai_wages_due_cents, ai_wages_paid_cents, pay_factor_bps,
                                           paid_costs_cents, unpaid_added_cents, profit_cents, founder_payout_cents, event_id,
                                           stake_payout_cents, campaign_id)
  values (p_company, v_start, v_qid, round(v_demand::numeric)::bigint, round(v_cap::numeric)::bigint, v_rev,
          v_crev, v_cogs, v_fixed, v_mk, v_pdue, v_ppaid, v_aidue, v_aipaid, v_factor, v_paid, v_unpaid, v_profit, v_payout,
          (v_ev ->> 'event_id')::uuid, v_stakes, v_camp.id);

  return jsonb_build_object('company_id', p_company, 'hour_start', v_start, 'quarter_id', v_qid, 'revenue_cents', v_rev,
                            'contract_revenue_cents', v_crev, 'profit_cents', v_profit, 'pay_factor_bps', v_factor,
                            'player_wages_paid_cents', v_ppaid, 'ai_wages_paid_cents', v_aipaid, 'unpaid_added_cents', v_unpaid,
                            'founder_payout_cents', v_payout, 'event_id', v_ev -> 'event_id', 'stake_payout_cents', v_stakes,
                            'campaign_id', v_camp.id);
end;
$$;

create or replace function public.company_tasks_state(p_player uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  cfg      jsonb := public.company_tasks_cfg();
  m        record;
  pc       public.player_companies;
  c        public.companies;
  v_ai_ok  boolean;
begin
  select * into m from public.company_task_member(p_player);
  if m.company_id is null then
    perform public.api_error('company_not_found');
  end if;
  select * into pc from public.player_companies where company_id = m.company_id;
  select * into c from public.companies where id = m.company_id;
  v_ai_ok := pc.ai_workers > 0
             and (m.is_founder or public.job_tier_rank(m.tier) >= public.job_tier_rank(cfg ->> 'aiDelegateMinTier'));
  return jsonb_build_object(
    'role', case when m.is_founder then 'founder' else 'employee' end,
    'company', jsonb_build_object('id', c.id, 'name', c.name, 'tier', pc.tier, 'product', pc.product_key),
    'momentum', coalesce(pc.task_momentum, 1.0),  -- ADR-148
    'my_tier', m.tier,
    'auto_ai', pc.tasks_auto_ai,
    'ai_workers', pc.ai_workers,
    'ai_minutes', public.company_task_ai_minutes(m.company_id),
    'can_use_ai', v_ai_ok,
    'people', coalesce((
      select jsonb_agg(jsonb_build_object(
               'nickname', p.nickname, 'tag', p.tag, 'tier', j.tier, 'is_me', j.player_id = p_player,
               'supervisor', (select s.nickname from public.profiles s where s.id = j.supervisor_id),
               'reports_to_me', case when m.is_founder then j.supervisor_id is null
                                     else coalesce(j.supervisor_id = p_player, false) end,
               'open_tasks', (select count(*) from public.company_tasks t
                               where t.company_id = m.company_id and t.assignee_id = j.player_id
                                 and t.status in ('assigned', 'playing')))
             order by public.job_tier_rank(j.tier::text) desc, p.nickname)
        from public.player_jobs j join public.profiles p on p.id = j.player_id
       where j.company_id = m.company_id and j.status = 'active'), '[]'::jsonb),
    'tasks', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', t.id, 'key', t.task_key, 'game', t.game, 'branch', t.branch, 'status', t.status,
               'value_cents', t.value_cents, 'created_at', t.created_at, 'due_at', t.due_at,
               'assignee', (select p.nickname from public.profiles p where p.id = t.assignee_id),
               'assignee_ai', t.assignee_ai,
               'assigned_by', (select p.nickname from public.profiles p where p.id = t.assigned_by),
               'ai_done_at', t.ai_done_at, 'opened_at', t.opened_at,
               'mine', coalesce(t.assignee_id = p_player, false),
               'can_delegate', t.status in ('open', 'assigned')
                               and (m.is_founder or t.status = 'open' or t.assignee_id = p_player))
             order by t.due_at)
        from public.company_tasks t
       where t.company_id = m.company_id and t.status in ('open', 'assigned', 'playing', 'ai')), '[]'::jsonb),
    'history', coalesce((
      select jsonb_agg(h order by h ->> 'resolved_at' desc)
        from (select jsonb_build_object('id', t.id, 'key', t.task_key, 'status', t.status, 'result_cents', t.result_cents,
                                        'score_bps', t.score_bps, 'ai', t.assignee_ai, 'resolved_at', t.resolved_at,
                                        'done_by', (select p.nickname from public.profiles p
                                                     where p.id = coalesce(t.done_by, t.assignee_id))) as h
                from public.company_tasks t
               where t.company_id = m.company_id and t.status in ('success', 'failure', 'missed')
               order by t.resolved_at desc
               limit (cfg ->> 'historyLimit')::integer) x), '[]'::jsonb));
end;
$$;

-- ===== supabase/migrations/20261204001900_ipo_hour.sql =====
-- =============================================================================
-- NEXA · 1900 · IPO within an hour, more AI investors and faster (ADR-149)
-- =============================================================================
-- The subscription window is now at most 60 minutes (startups.ipo.subscriptionMinutes). AI investors take a bigger
-- part (aiTakeBase 0.6 + aiTakePerQuality 0.4: 60 to 100 % of the offer) and most of it early: their share after a
-- fraction t of the window is 1 - (1 - t)^aiPace (aiPace 3). Once everything is subscribed, close_due_offers lists
-- the company at once (ADR-146). Only share_offer_ai_topup() changes; the values come from game_config.
-- Idempotent: runs unchanged as supabase/updates/20261204001900_ipo_hour.sql.

create or replace function public.share_offer_ai_topup(p_offer_id uuid, p_now timestamptz, p_final boolean)
returns bigint
language plpgsql
security definer
set search_path = ''
as $$
declare
  o        public.company_share_offers;
  v_ipo    jsonb := coalesce(public.config_jsonb('startups', '{ipo}'), '{}'::jsonb);
  v_q      double precision;
  v_target bigint;
  v_frac   numeric;
  v_due    bigint;
  v_add    bigint;
  v_pay    bigint;
  v_founder uuid;
begin
  select * into o from public.company_share_offers where id = p_offer_id and status = 'open' for update;
  if o.id is null then
    return 0;
  end if;
  select coalesce(pc.quality, 0), pc.founder_id into v_q, v_founder from public.player_companies pc where pc.company_id = o.company_id;
  v_target := floor(o.shares_offered_e6
                    * least(1, greatest(0, public.cfg_num(v_ipo, '{aiTakeBase}', 0.2)
                                           + public.cfg_num(v_ipo, '{aiTakePerQuality}', 0.5) * coalesce(v_q, 0))))::bigint;
  v_frac := case when p_final or o.ends_at <= o.created_at then 1
                 else least(1, greatest(0, extract(epoch from (coalesce(p_now, now()) - o.created_at))
                                           / extract(epoch from (o.ends_at - o.created_at)))) end;
  -- ADR-149: most AI investors come in early: 1 - (1 - t)^aiPace
  v_frac := 1 - power(1 - v_frac, greatest(1, public.cfg_num(v_ipo, '{aiPace}', 1)));
  v_due := least(floor(v_target * v_frac)::bigint, o.shares_offered_e6 - o.shares_subscribed_e6);
  v_add := v_due - o.shares_ai_e6;
  if v_add <= 0 then
    return 0;
  end if;
  -- telescoping: the payments add up to floor(all AI shares x price) exactly
  v_pay := floor((o.shares_ai_e6 + v_add)::numeric * o.price_cents / 1000000)::bigint
         - floor(o.shares_ai_e6::numeric * o.price_cents / 1000000)::bigint;
  if v_pay > 0 then
    perform public.ledger_transfer(public.ledger_system_account('market'), public.company_cash_account(o.company_id), v_pay,
                                   'transfer', 'Zeichnung durch Investoren', 'share_offer', o.id,
                                   'offer-ai:' || o.id::text || ':' || (o.shares_ai_e6 + v_add)::text, v_founder);
  end if;
  update public.company_share_offers set shares_ai_e6 = shares_ai_e6 + v_add where id = o.id;
  return v_add;
end;
$$;

